/*
 * 中学英語・中学国語(高校入試レベル)の追加単元のテキスト本文。このアプリのオリジナル。
 * 書式は js/data/lessons_1.js の冒頭コメントを参照。
 * 読解の例文は、古典の一節を除き、すべてこのアプリで作った作例。
 */
window.WPS = window.WPS || {};
WPS.LESSONS = WPS.LESSONS || {};
(function (L) {
  var INONAT = '<svg viewBox="0 0 220 150" class="lz-fig" role="img" aria-label="前置詞 at・on・in のイメージ。at は点(時刻・地点)、on は面に接する(日付・曜日)、in は範囲の中(月・年・国)"><circle cx="37" cy="62" r="5" class="pt"/><line x1="82" y1="75" x2="140" y2="75" class="ax"/><rect x="100" y="55" width="20" height="20" class="bx"/><circle cx="182" cy="62" r="24" class="tr"/><circle cx="182" cy="62" r="4" class="pt"/><text x="30" y="30">at</text><text x="103" y="30">on</text><text x="177" y="30">in</text><text x="31" y="100">点</text><text x="105" y="100">面</text><text x="171" y="100">範囲</text><text x="10" y="118">時刻・地点</text><text x="89" y="118">日・曜日</text><text x="155" y="118">月・年・国</text></svg>';
  var PARA = '<svg viewBox="0 0 220 150" class="lz-fig" role="img" aria-label="英語の段落の基本構成。トピック・センテンスで主題を示し、サポーティング・センテンスで理由や具体例を述べ、最後にまとめる"><rect x="20" y="10" width="180" height="30" class="bx"/><rect x="20" y="60" width="180" height="30" class="bx"/><rect x="20" y="110" width="180" height="30" class="bx"/><line x1="110" y1="40" x2="110" y2="60" class="ax"/><line x1="110" y1="90" x2="110" y2="110" class="ax"/><text x="30" y="29">Topic sentence=主題</text><text x="30" y="79">Supporting=理由・具体例</text><text x="30" y="129">Conclusion=まとめ</text></svg>';

  // ===== 中学英語:会話表現 =====
  L.e_talk = {
    goal: '依頼・許可・申し出・提案・誘いの表現を「だれが動くか」で使い分け、電話・道案内・買い物の場面で、決まった言い方とその答え方を正しく選べるようになる。',
    intro: '英語の会話問題は、文法の知識だけでなく「この場面ではこう言う」という決まった言い方(会話表現)を知っているかどうかで差がつきます。日本語でも「ちょっと手伝ってくれる?」と「手伝いましょうか?」では、動く人がちがいますね。英語も同じで、まず「だれが動くのか」を考えると、たくさんある表現がすっきり整理できます。',
    pre: '【助動詞】は、動詞の前に置いて意味をそえる語です。can(〜できる・〜してよい)、will(〜するつもりだ・〜だろう)、may(〜してよい・〜かもしれない)、shall(〜しましょうか)などがあり、後ろの動詞は必ず【原形】になります。\n助動詞の疑問文は、助動詞を主語の前に出して作ります。例:You can swim. → Can you swim?(あなたは泳げますか)\n【Could】は can の過去形、【Would】は will の過去形ですが、会話では過去の意味ではなく、【ていねいな言い方】として使われることが多いです。Could you 〜? は Can you 〜? よりていねいです。\n会話文の問題では、空所の前だけでなく【後ろの返事】が大きなヒントになります。返事が Sure.(いいですよ)なのか、I\'m sorry, but 〜.(ごめんなさい、〜)なのかで、入る文が決まります。',
    secs: [
      { h: '「だれが動くか」で4つに分ける', t: 'なぜ会話表現は混乱しやすいのでしょうか。それは、Can you 〜? / Can I 〜? / Shall I 〜? / Shall we 〜? のように、形がよく似ているからです。そこで、主語に注目して「だれが動くか」で分けます。\n【相手が動く】…依頼(頼む)。Can you 〜? / Could you 〜? / Will you 〜?(〜してくれますか)。例:Can you open the door?(ドアを開けてくれますか)\n【自分が動いてよいか】…許可を求める。Can I 〜? / May I 〜?(〜してもいいですか)。例:May I use your pen?(あなたのペンを使ってもいいですか)\n【自分が動きましょうか】…申し出。Shall I 〜?(私が〜しましょうか)。例:Shall I help you?(手伝いましょうか)\n【いっしょに動こう】…提案・誘い。Shall we 〜? / Let\'s 〜.(〜しましょう)。例:Shall we go shopping?(買い物に行きましょうか)\nこのように主語が you なら相手、I なら自分、we なら「自分たちみんな」が動きます。問題を見たら、まず主語に丸をつけましょう。',
        key: '主語が you=相手に頼む、I=自分の許可・申し出、we=いっしょに誘う。まず主語を見る。',
        ex: [{ q: '次の日本語に合う英文を選ぼう。「(私が)窓を閉めましょうか。」\nア Shall we close the window?  イ Shall I close the window?  ウ Can you close the window?', hint: '動くのはだれでしょうか。', steps: ['日本語の「(私が)〜しましょうか」は、自分が動くことを申し出る文。', '自分が動くので、主語は I。', '申し出の決まった形は Shall I 〜?。', 'アは「いっしょに閉めましょうか」、ウは「閉めてくれますか」(相手が動く)になる。'], a: 'イ Shall I close the window?', check: '答え方も確かめます。Shall I 〜? には Yes, please.(お願いします)や No, thank you.(けっこうです)と答えます。' }] },
      { h: '依頼と許可:答え方まで覚える', t: '依頼や許可の表現は、それだけ覚えても点になりません。会話問題では【答え方】を選ばせることが多いからです。\n依頼(Can you 〜? / Could you 〜? / Will you 〜?)への答え方:引き受けるなら Sure.(いいですよ)/ OK. / All right. / No problem.(いいですよ)。断るなら I\'m sorry, but I can\'t.(ごめんなさい、できません)のように、理由をそえることが多いです。\n許可(Can I 〜? / May I 〜?)への答え方:許すなら Sure. / Of course.(もちろん)/ Go ahead.(どうぞ)。許さないなら I\'m sorry, but 〜.(ごめんなさい、〜)と理由を言います。\nていねいさの順:Can you 〜? より Could you 〜? のほうがていねいです。許可では Can I 〜? より May I 〜? のほうがていねいで、お店の人がお客さんに May I help you?(いらっしゃいませ・何かお探しですか)と言うのはこのためです。\nWould you 〜? も「〜していただけますか」というていねいな依頼です。Would you mind 〜ing? のような発展的な表現は、高校で学びます。',
        key: '依頼・許可には Sure. / Of course. で応じ、断るときは I\'m sorry, but 〜. と理由をそえる。',
        ex: [{ q: '( )に入る最も適切な文を選ぼう。\nA: Could you carry this box with me?\nB: (   ) It\'s heavy, isn\'t it?\nア Sure.  イ No, thank you.  ウ Yes, let\'s.  エ Here you are.', hint: 'B は後ろで「重いですよね」と言っています。引き受けたのか、断ったのか考えましょう。', steps: ['A の Could you 〜? は「〜していただけますか」という依頼。', 'B は It\'s heavy, isn\'t it?(重いですよね)と、運ぶことを前提に話している。', '依頼を引き受けるので Sure.(いいですよ)が入る。', 'No, thank you. は申し出を断る言い方、Yes, let\'s. は誘いへの答え、Here you are. は物を渡すときの言い方。'], a: 'ア Sure.', check: '会話全体を訳して「この箱をいっしょに運んでくれますか」「いいですよ。重いですよね」と自然につながるか確かめます。' }] },
      { h: '提案・誘い:Let\'s / Shall we / How about', t: '友だちを何かに誘ったり、「こうしたらどう?」と提案したりする表現は、入試の会話文に毎年のように出ます。\n【Let\'s 〜.】(〜しましょう)… Let\'s play tennis. 答え方:Yes, let\'s. / OK. / That sounds good.(いいですね)。\n【Shall we 〜?】(〜しましょうか)… Shall we play tennis? 答え方:Yes, let\'s. / No, let\'s not.(やめておきましょう)。\n【How about 〜?】(〜はどうですか)… How about going to the park?(公園に行くのはどう?)。about は前置詞なので、後ろは名詞か【動名詞(〜ing)】です。How about tomorrow?(明日はどう?)のように名詞も置けます。\n【Why don\'t we 〜?】(〜しませんか)… Why don\'t we eat lunch together?(いっしょにお昼を食べませんか)。形は「なぜ〜しないのか」ですが、誘いの意味で使われます。\n【Would you like to 〜?】(〜したいですか・〜しませんか)… Would you like to come to my party?(パーティーに来ませんか)。答え方:I\'d love to.(ぜひそうしたいです)/ I\'m sorry, but I can\'t. また、Would you like some tea?(お茶はいかがですか)のように、後ろに名詞を置くと物をすすめる表現になります。',
        key: 'How about の後ろは名詞か〜ing。Would you like to 〜? には I\'d love to. で応じる。',
        ex: [{ q: '( )に適する語を入れよう。「放課後、図書館で勉強するのはどう?」\nHow about (   ) in the library after school?', hint: 'about のあとに動詞を置くときの形を思い出しましょう。', steps: ['How about 〜? は「〜はどうですか」という提案の表現。', 'about は前置詞なので、後ろに動詞を置くときは動名詞(〜ing)にする。', 'study(勉強する)を動名詞にすると studying。'], a: 'studying', check: 'How about to study / How about study としていないか見直します。前置詞の後ろは〜ing、が合言葉です。' }] },
      { h: '電話の決まり文句', t: '電話では相手の顔が見えないため、日本語の「もしもし」「〜ですが」と同じように、英語にも決まった言い方があります。英語の電話表現は、日本語と言い方がかなりちがうので、そのまま覚えるのが近道です。\n名乗るとき:Hello. This is Ken.(もしもし、ケンです)。電話では I am Ken. ではなく【This is 〜.】を使います。\n相手を呼び出すとき:May I speak to Yumi?(ユミさんをお願いできますか)/ Can I speak to Yumi?\n本人が出たとき:Speaking.(私です)。待ってもらうとき:Hold on, please.(少々お待ちください)/ Just a minute.\n本人がいないとき:Can I take a message?(伝言をうけたまわりましょうか)←受ける側。Can I leave a message?(伝言をお願いできますか)←かけた側。take(受ける)と leave(残す)の向きのちがいに注意しましょう。\nまちがい電話:I\'m sorry, you have the wrong number.(番号をおまちがえですよ)。かけ直してほしいとき:Could you call me back later?(あとでかけ直していただけますか)',
        key: '電話では This is 〜.(〜です)。伝言は、受ける側が take a message、かけた側が leave a message。',
        ex: [{ q: '( )に入る文を選ぼう。\nA: Hello. This is Mika. May I speak to Tom?\nB: I\'m sorry, he\'s out now. (   )\nA: Yes, please. Please tell him to call me back.\nア Can I take a message?  イ Can I leave a message?  ウ Speaking.  エ Hold on, please.', hint: 'B はトムの家族です。A は「はい、お願いします。かけ直すよう伝えて」と答えています。', steps: ['B は「トムは今、外出しています」と言っているので、トム本人ではない。', 'A は後で「かけ直すように伝えてください」と伝言を頼んでいる。', 'つまり B は「伝言をうけたまわりましょうか」と申し出たはず。', '受ける側の言い方は take a message。leave a message はかけた側が言う。'], a: 'ア Can I take a message?', check: 'Speaking. は本人が出たとき、Hold on, please. は取り次ぐときの言い方なので、トムがいないこの場面には合いません。' }] },
      { h: '道案内:たずね方と教え方', t: '道案内は、地図や絵を見ながら答える問題として高校入試によく出ます。たずね方・教え方・位置の言い方の3つに分けて覚えます。\nたずね方:Excuse me. Could you tell me the way to the station?(すみません、駅への道を教えていただけますか)/ How can I get to the station?(駅へはどうやって行けますか)/ Where is the station?\n教え方:Go straight.(まっすぐ行ってください)/ Go along this street.(この通りにそって行ってください)/ Turn left at the second corner.(2つめの角を左に曲がってください)/ Turn right at the bank.(銀行のところで右に曲がってください)\n位置の言い方:It\'s on your right.(右手にあります)/ It\'s on your left.(左手にあります)/ It\'s next to the post office.(郵便局のとなりです)/ It\'s between the bank and the hospital.(銀行と病院の間です)/ You can\'t miss it.(すぐに分かりますよ)\nかかる時間:How long does it take?(どれくらいかかりますか)— It takes about ten minutes.(10分くらいかかります)\n地図問題では、指で道をたどりながら読むのがコツです。「2つめの角」なら、出発点から数えて2つめの曲がり角で曲がります。',
        key: '道案内は「Go straight → Turn left/right at 〜 → It\'s on your right/left.」の順。地図は指でたどる。',
        ex: [{ q: '次の案内を日本語にしよう。\nGo straight and turn right at the second corner. The library is on your left. It\'s next to the park.', hint: '文を1つずつ区切って訳しましょう。', steps: ['Go straight =まっすぐ行く。', 'turn right at the second corner = 2つめの角で右に曲がる。', 'The library is on your left. =図書館は(あなたの)左手にある。', 'It\'s next to the park. =それ(図書館)は公園のとなりにある。'], a: 'まっすぐ行って、2つめの角を右に曲がってください。図書館は左手にあります。公園のとなりです。', check: '右に曲がったあと「左手」にあるので、曲がる方向と建物のある側が同じとは限りません。地図問題ではここで取りちがえないように確かめます。' }] },
      { h: '買い物の会話', t: '買い物の会話は、店員とお客さんのどちらが話しているかを意識すると分かりやすくなります。\n店員の言葉:May I help you?(いらっしゃいませ・何かお探しですか)/ What color do you like?(何色がお好きですか)/ How about this one?(こちらはいかがですか)/ Here you are.(はい、どうぞ)\nお客さんの言葉:I\'m looking for a T-shirt.(Tシャツを探しています)/ I\'m just looking.(見ているだけです)/ Can I try it on?(試着してもいいですか)/ Do you have a smaller one?(もっと小さいものはありますか)/ How much is it?(いくらですか)/ I\'ll take it.(それをください)\none は、前に出た名詞のくり返しをさけるための語です。a smaller one は a smaller T-shirt のことです。\nMay I help you? に対して、探しているものがあれば Yes, please. I\'m looking for 〜.、とくになければ No, thank you. I\'m just looking. と答えます。',
        key: 'I\'ll take it.=買います。I\'m just looking.=見ているだけ。one は前の名詞のくり返し。' }
    ],
    faq: [['Can you 〜? と Could you 〜? は、どちらを使えばいいの?', 'どちらも「〜してくれますか」という依頼で、Could you 〜? のほうがていねいです。友だちには Can you 〜?、先生や初めて会う人には Could you 〜? が自然です。入試では、どちらも依頼の表現として選べれば十分です。'], ['Shall we 〜? と Let\'s 〜. は同じ意味?', 'ほぼ同じで、どちらも「いっしょに〜しよう」という誘いです。Let\'s 〜. は「〜しよう」と言い切る形、Shall we 〜? は「〜しましょうか」とたずねる形です。答え方はどちらも Yes, let\'s. が使えます。'], ['会話文の問題で、空所に入る文がどうしても決まらないときは?', '空所の【直後】の文を読みましょう。直後が理由をつけた断りなら空所は I\'m sorry 〜、Yes, please. なら空所は申し出(Shall I 〜? など)というように、返事から逆に決まることが多いです。']],
    terms: [['依頼', '相手に「〜してくれますか」と頼むこと。Can/Could/Will you 〜?'], ['許可', '「〜してもいいですか」と自分がしてよいかたずねること。Can/May I 〜?'], ['申し出', '「(私が)〜しましょうか」と自分から言い出すこと。Shall I 〜?'], ['誘い・提案', '「いっしょに〜しよう」「〜はどう?」と持ちかけること。Shall we 〜? / Let\'s 〜. / How about 〜?'], ['This is 〜.', '電話で名乗るときの言い方(〜です)'], ['take a message / leave a message', '伝言を受ける/伝言を残す'], ['on your right', '(あなたの)右手に。道案内で位置を示す言い方']],
    miss: ['Shall I 〜? に Yes, let\'s. と答えてしまう。Shall I は「私が〜しましょうか」なので Yes, please. が正しい。答え方は表現とセットで覚えて防ぐ。', 'How about to go 〜? / How about go 〜? と書いてしまう。about は前置詞なので後ろは〜ing。「前置詞の後ろは〜ing」と唱えて防ぐ。', '電話で I am Ken. と名乗ってしまう。電話では This is Ken. を使う。場面ごとの決まり文句として覚える。', '伝言の take と leave を逆にする。受け取る側が take、置いていく側が leave と、物の動きの向きで覚える。'],
    sum: ['会話表現は「だれが動くか」で分ける:you=依頼、I=許可・申し出、we=誘い。', '依頼・許可には Sure. / Of course.、断るときは I\'m sorry, but 〜. と理由をそえる。', 'Shall I 〜? には Yes, please. / No, thank you.、Shall we 〜? には Yes, let\'s. / No, let\'s not.。', '電話は This is 〜. / May I speak to 〜? / Hold on, please. / Can I take a message?。', '道案内は Go straight / Turn left at 〜 / It\'s on your right.、買い物は May I help you? / I\'ll take it.。'],
    next: '会話の流れを長い文章の中で読む練習として「長文読解(e_read)」へ進みましょう。'
  };

  // ===== 中学英語:前置詞と代名詞 =====
  L.e_prep = {
    goal: '時・場所を表す前置詞(at・on・in など)を範囲の広さで使い分け、人称代名詞と所有代名詞を文の中の働きに合わせて正しい形で使えるようになる。',
    intro: '日本語では「7時に」「月曜日に」「5月に」と、どれも「に」で表せます。ところが英語では、at seven、on Monday、in May と、前置詞がすべてちがいます。また、「彼」も he・his・him と形が変わります。どちらもバラバラに暗記するとすぐ混ざりますが、「なぜその形になるのか」というルールを知れば、ほとんど迷わなくなります。',
    pre: '【前置詞】は、名詞や代名詞の前に置いて、時・場所・方向などを表す語です。in、on、at、for、from、to、with などがあります。「前に置く詞(ことば)」だから前置詞といいます。\n前置詞の後ろには、名詞・代名詞・動名詞(〜ing)が来ます。代名詞が来るときは、me・him・her のような【目的格】になります。例:with him(彼といっしょに)\n【代名詞】は、名詞のくり返しをさけるために、名詞の代わりに使う語です。I・you・he・she・it・we・they などがあります。\n英語では、主語(〜は)、目的語(〜を・〜に)など、文の中の働きによって代名詞の形が変わります。この形のことを【格】といいます。',
    secs: [
      { h: '時を表す at・on・in', t: 'なぜ at・on・in を使い分けるのでしょうか。英語では、時間を「点」「1日というまとまり」「もっと広い範囲」のように、範囲の広さで区別するからです。\n【at】…時刻など、時の一点。at seven(7時に)/ at noon(正午に)/ at night(夜に)\n【on】…日付・曜日など、特定の日。on Monday(月曜日に)/ on May 5(5月5日に)/ on Sunday morning(日曜日の朝に)\n【in】…月・季節・年・世紀など、広い期間。in May(5月に)/ in summer(夏に)/ in 2025(2025年に)/ in the morning(午前中に)\n注意したいのは in the morning と on Sunday morning のちがいです。ただの「朝に」は in ですが、「日曜日の朝」のように特定の日がつくと on になります。\nまた、this・next・last・every がつくときは前置詞を使いません。× on next Sunday → ○ next Sunday(次の日曜日に)、× in last year → ○ last year(去年)',
        key: '時の前置詞:at=時刻(点)、on=日付・曜日、in=月・季節・年。this/next/last/every の前には前置詞を置かない。',
        fig: INONAT,
        ex: [{ q: '( )に at・on・in のどれかを入れよう。\n(1) The game starts (   ) 3:30.\n(2) We have no school (   ) Saturday.\n(3) It is very hot here (   ) August.', hint: '時刻・曜日・月のどれにあたるか考えましょう。', steps: ['(1) 3:30 は時刻、つまり時の一点なので at。', '(2) Saturday は曜日なので on。', '(3) August(8月)は月なので in。'], a: '(1) at (2) on (3) in', check: '訳して確かめます。(1)試合は3時30分に始まる。(2)土曜日は学校がない。(3)ここは8月はとても暑い。' }] },
      { h: '場所を表す at・on・in と、そのほかの前置詞', t: '場所の前置詞も、時と同じ考え方で整理できます。\n【at】…地点(点としてとらえた場所)。at the station(駅で)/ at the bus stop(バス停で)/ at home(家で)\n【in】…広がりのある空間や地域の中。in the box(箱の中に)/ in the room(部屋の中で)/ in Japan(日本で)\n【on】…面に接している。on the desk(机の上に)/ on the wall(壁に)/ on the ceiling(天井に)。on は「上」ではなく【接触】を表すので、天井にはりついていても on です。\nそのほかの場所の前置詞:under(〜の下に)、near(〜の近くに)、by(〜のそばに)、in front of(〜の前に)、behind(〜の後ろに)、between A and B(AとBの間に)、among(3つ以上のものの間に)。\nたとえば There is a cat under the table.(テーブルの下にねこがいる)、The bank is between the hospital and the school.(銀行は病院と学校の間にある)のように使います。',
        key: '場所:at=地点、in=空間の中、on=面に接触。between は2つの間、among は3つ以上の間。',
        ex: [{ q: '( )に適する前置詞を入れよう。\n(1) There is a clock (   ) the wall.\n(2) My house is (   ) the park and the library.\n(3) Let\'s meet (   ) the station.', hint: '(1)は接触、(2)は「AとBの間」、(3)は待ち合わせの地点です。', steps: ['(1) 時計は壁に接してかかっているので on。', '(2) the park and the library の2つの間なので between。', '(3) 駅という地点で会うので at。'], a: '(1) on (2) between (3) at', check: '(2)は and がある2つのものの間なので between。among は3つ以上の間なので使えません。' }] },
      { h: 'まぎらわしい前置詞:by と until、for と during', t: '高校入試で特によくまちがえられるのが、by と until、for と during の区別です。日本語にすると似てしまうので、意味のちがいをはっきりさせます。\n【by】…「〜までに」という期限。その時までに1回行えばよい動作に使います。Finish the work by five.(5時までにその仕事を終えなさい)\n【until(till)】…「〜までずっと」という継続。その時まで続く状態や動作に使います。I waited for him until five.(私は5時までずっと彼を待った)\n【for】…「〜の間」。for three days(3日間)のように、【数字で長さ】を表すときに使います。\n【during】…「〜の間に」。during the summer vacation(夏休みの間に)のように、【特定の期間の名前】と使います。\n見分け方:by と until は「終える・提出する」(1回で済む)なら by、「待つ・いる・続ける」なら until。for と during は、後ろが数字なら for、行事や期間の名前なら during です。',
        key: 'by=〜までに(期限)、until=〜までずっと(継続)。for+数字の期間、during+期間の名前。',
        ex: [{ q: '( )に適する語を選ぼう。\n(1) Please come back (by / until) six.\n(2) It rained (for / during) two hours.', hint: '(1)は「帰ってくる」が続く動作かどうか、(2)は後ろが数字かどうかを見ましょう。', steps: ['(1) come back(帰ってくる)は1回で済む動作なので、「6時までに」の by。', '(2) two hours は数字で表した長さなので for。', '訳:(1)6時までに戻ってきてください。(2)2時間雨が降った。'], a: '(1) by (2) for', check: '(1)を until にすると「6時までずっと帰ってくる」となり、意味が通りません。' }] },
      { h: '人称代名詞の変化表', t: '代名詞は、文の中での働きによって形が変わります。なぜ形が変わるかというと、英語は語順と形で「だれが」「だれを」を区別する言語だからです。\n変化表(主格〜は/所有格〜の/目的格〜を・に/所有代名詞〜のもの):\nI - my - me - mine、you - your - you - yours、he - his - him - his、she - her - her - hers、it - its - it - (なし)、we - our - us - ours、they - their - them - theirs\n【主格】は主語の位置で使います。She plays tennis.\n【所有格】は名詞の前に置いて「〜の」を表します。This is her racket.\n【目的格】は動詞や前置詞の後ろで使います。I like her. / I play tennis with her.\nhe の所有格と所有代名詞はどちらも his、she の所有格と目的格はどちらも her なので、位置で見分けます。',
        key: '代名詞は位置で形が決まる:主語=主格、名詞の前=所有格、動詞・前置詞の後ろ=目的格。',
        ex: [{ q: '( )内の語を適する形にしよう。\n(1) This is Mr. Sato. Do you know (he)?\n(2) Ken and I are friends. (we) school is near the river.', hint: '(1)は動詞 know の後ろ、(2)は名詞 school の前です。', steps: ['(1) know の目的語の位置なので目的格にする。he の目的格は him。', '(2) school(名詞)の前で「私たちの」という意味なので所有格。we の所有格は our。', '文頭なので大文字で始めて Our とする。'], a: '(1) him (2) Our', check: '訳して確かめます。(1)こちらは佐藤先生です。あなたは彼を知っていますか。(2)ケンと私は友だちです。私たちの学校は川の近くにあります。' }] },
      { h: '所有代名詞と「〜の」の表し方', t: '【所有代名詞】は「〜のもの」という意味で、1語で「所有格＋名詞」の働きをします。mine = my bike のように、名詞をくり返さずにすみます。\n例:This bike is mine.(この自転車は私のものです)/ Whose bag is this? — It\'s hers.(これはだれのかばんですか。— 彼女のものです)\n人の名前を使って「〜の」を表すときは【\'s】をつけます。Ken\'s bag(ケンのかばん)。「〜のもの」も同じ形で、This bag is Ken\'s.(このかばんはケンのものです)と言えます。\n【Whose】は「だれの・だれのもの」をたずねる疑問詞です。Whose pen is this? / Whose is this pen? どちらも「これはだれのペンですか」の意味です。\n【its と it\'s】は特にまちがえやすい組み合わせです。its は所有格「その・それの」、it\'s は it is(または it has)の短縮形です。The dog wagged its tail.(その犬はしっぽをふった)',
        key: 'mine=my＋名詞。人名は\'s で「〜の・〜のもの」。its(その)と it\'s(それは〜だ)を区別する。',
        ex: [{ q: '同じ意味になるように( )に1語入れよう。\nThis is my umbrella. = This umbrella is (   ).', hint: '「私のかさ」を「私のもの」に言いかえます。', steps: ['左の文は「これは私のかさです」。', '右の文は「このかさは〜です」なので、「私のもの」が入る。', '「私のもの」は所有代名詞 mine。'], a: 'mine', check: 'my を入れると後ろに名詞がないので誤りです。所有格の後ろには必ず名詞が来ます。' }] }
    ],
    faq: [['at night なのに in the morning なのはなぜ?', '「午前中」「午後」「夕方」はある程度の長さの時間帯なので in the morning / in the afternoon / in the evening ですが、night は昔からの決まった言い方として at night を使います。理屈より決まり文句として覚えましょう。'], ['at home と in the house は、どうちがうの?', 'at home は「家で(くつろいで)」と生活の場所を点としてとらえる言い方、in the house は「家という建物の中に」と空間を意識した言い方です。中学では「家で」は at home と覚えておけば十分です。'], ['it の所有代名詞がないのはなぜ?', '「それのもの」と言う場面がほとんどないため、ふつうは使いません。変化表では空らんにしておきましょう。']],
    terms: [['前置詞', '名詞や代名詞の前に置き、時・場所などを表す語'], ['主格', '主語として使う代名詞の形(I・he など)'], ['所有格', '名詞の前で「〜の」を表す形(my・his など)'], ['目的格', '動詞や前置詞の後ろで使う形(me・him など)'], ['所有代名詞', '「〜のもの」を1語で表す形(mine・yours など)'], ['by / until', '〜までに(期限)/〜までずっと(継続)'], ['for / during', '数字で表した期間/特定の期間の名前とともに「〜の間」']],
    miss: ['on next Sunday のように next や last の前に前置詞をつける。next・last・this・every がつくと前置詞は不要、と覚えて防ぐ。', 'I play with he. のように前置詞の後ろに主格を置く。前置詞の後ろは目的格(him)と決まっていることを確認する。', 'This is mine bike. のように所有代名詞の後ろに名詞を置く。mine は1語で「私のもの」なので、名詞を置くなら my bike にする。', 'Finish it until Friday. と期限に until を使う。終える・提出するなど1回で済む動作の期限は by を使う。', 'its と it\'s を取りちがえる。it is に言いかえられるかどうかを確かめて防ぐ。'],
    sum: ['時:at=時刻、on=日付・曜日、in=月・季節・年。next・last などの前には前置詞を置かない。', '場所:at=地点、in=空間の中、on=面に接触。between は2つ、among は3つ以上の間。', 'by=〜までに(期限)、until=〜までずっと。for+数字、during+期間の名前。', '代名詞は位置で形が決まる:主格・所有格・目的格・所有代名詞(I-my-me-mine)。', '前置詞の後ろの代名詞は目的格。its(その)と it\'s(it is)を区別する。'],
    next: '前置詞と代名詞は、会話でも長文でも毎回使います。次は「会話表現(e_talk)」で、道案内などの場面で使ってみましょう。'
  };

  // ===== 中学英語:長文読解 =====
  L.e_read = {
    goal: '英語の段落の組み立て(トピック・センテンス)と、つなぎことば・指示語を手がかりに長文の要点をつかみ、高校入試の設問の型ごとに正しい答え方ができるようになる。',
    intro: '長文読解が苦手な人の多くは、1語ずつ日本語に直しながら読み、途中で「何の話だったっけ」となってしまいます。でも、英語の文章には決まった組み立てがあります。どこに大事なことが書かれやすいか、どの語が話の向きを変える目印になるかを知っておけば、知らない単語があっても筋をつかめます。この単元では、入試本番で使える「読み方の型」を身につけます。',
    pre: '英文は、まず【主語と動詞】を見つけることが読む基本です。主語は「〜は・が」、動詞は「〜する・〜である」にあたります。長い文でも、主語と動詞をつかめば骨組みが分かります。\n【接続詞】は、文と文をつなぐ語です。and(そして)、but(しかし)、so(だから)、because(なぜなら〜だから)、when(〜するとき)、if(もし〜なら)などがあります。\n関係代名詞(who・which・that)は、名詞に後ろから説明を加えます。例:the boy who is playing tennis(テニスをしている少年)。長文では、このような「名詞＋説明」のかたまりが多く出てきます。\n現在完了(have＋過去分詞)は、「ずっと〜している」「〜したことがある」「〜したところだ」を表します。長文の書き出しでよく使われる形です。',
    secs: [
      { h: '英語の段落は「主題→説明→まとめ」', t: 'なぜ英語の段落は読みやすい形をしているのでしょうか。英語の文章は、読む人に「まず結論、次に理由」と伝える書き方が基本になっているからです。\n段落の最初の文を【トピック・センテンス】といい、その段落で言いたいこと(主題)を示します。その後に、理由・具体例・説明を加える【サポーティング・センテンス】が続き、最後にまとめの文が来ることもあります。\n作例:Walking is good for our health. It makes our legs strong. It also helps us sleep well. So, let\'s walk more.\n訳:歩くことは健康によい。足を強くしてくれる。また、よく眠る助けにもなる。だから、もっと歩こう。\nこの段落では、最初の文が主題(歩くことは健康によい)、2・3文目が理由、最後がまとめです。各段落の最初の文を拾い読みするだけでも、文章全体の流れがおおよそつかめます。',
        key: '段落の最初の文(トピック・センテンス)に主題がある。最初の文を拾うと全体の流れが見える。',
        fig: PARA,
        ex: [{ q: '次の段落のトピック・センテンス(主題を示す文)はどれ?\n①Our town has many good points. ②There is a large park near the station. ③People are kind to visitors. ④The food is also delicious.', hint: 'ほかの文をまとめて言っている文を探しましょう。', steps: ['各文を訳す。①私たちの町にはよいところがたくさんある。②駅の近くに大きな公園がある。③人々は訪問者に親切だ。④食べ物もおいしい。', '②〜④は、町のよいところの具体例になっている。', '①は、②〜④をまとめて言っている文。'], a: '①', check: '①を消すと②〜④が何のために書かれているか分からなくなり、②〜④を消しても①の主張は残ります。これが主題の文である証拠です。' }] },
      { h: 'つなぎことばで「話の向き」を読む', t: '長文の中で、話の向きを示す語を【つなぎことば(ディスコースマーカー)】とよびます。道路標識のように「この先どうなるか」を教えてくれる語です。\n【逆接】… but / however(しかし)。後ろに前と反対の内容が来ます。筆者の本当に言いたいことは however の後ろにあることが多いです。\n【例示】… for example / for instance(たとえば)。後ろは具体例です。例は主張を支える材料なので、主張そのものではありません。\n【追加】… also / in addition / besides(さらに、そのうえ)。前と同じ方向の内容を加えます。\n【結果・結論】… so / therefore(だから、したがって)/ in short(要するに)。後ろにまとめや結論が来ます。\n【順序】… first / second / then / finally(最初に・次に・それから・最後に)。理由や手順を並べるときに使います。',
        key: 'however の後ろは筆者の言いたいこと、for example の後ろは具体例、so の後ろは結論。',
        ex: [{ q: '( )に入る語を選ぼう。\nMany people think that cats do not like water. (   ), some cats enjoy swimming.\nア However  イ For example  ウ So  エ Also', hint: '前の文と後ろの文は、同じ方向ですか、反対ですか。', steps: ['前の文:多くの人は、ねこは水が好きではないと思っている。', '後ろの文:泳ぐのを楽しむねこもいる。', '「水が好きではない」と「泳ぐのを楽しむ」は反対の内容なので逆接。', '逆接のつなぎことばは However。'], a: 'ア However', check: 'So を入れると「だから泳ぐのを楽しむ」となり、前後の内容が理由と結果の関係にならないので不適です。' }] },
      { h: '指示語が指すものを見つける', t: '入試では「下線部の it は何を指しますか」「this の内容を日本語で書きなさい」という問題がよく出ます。指示語を正しく読めないと、文章の筋もずれてしまいます。\n【it】…前に出た単数の「もの・こと・動物」を指します。they / them は複数の人やものを指します。\n【this / that】…前の語だけでなく、前の文全体の内容を指すことがあります。This made me happy.(このことが私を喜ばせた)の this は、直前の文の内容であることが多いです。\n見つけ方の手順:①指示語より前を探す(ふつうは直前)。②単数か複数か、人かものかを確かめる。③見つけた候補を指示語の位置に入れて、意味が通るか読み直す。\n日本語で答えるときは、「〜こと」の形でまとめると答えやすくなります。',
        key: '指示語は直前から探し、候補を当てはめて意味が通るか読み直す。this は前の文全体を指すことがある。',
        ex: [{ q: '下線部 This が指す内容を日本語で答えよう。\nMy grandmother started to learn English at the age of seventy. This surprised me.', hint: '直前の文の内容をまとめましょう。', steps: ['This は、ふつう直前の文の内容を指す。', '直前の文:祖母は70歳で英語を学び始めた。', 'This の位置に入れると「祖母が70歳で英語を学び始めたことが私を驚かせた」となり、意味が通る。', '「〜こと」の形で答える。'], a: '祖母が70歳で英語を学び始めたこと。', check: '答えを This の位置に入れた文が自然な日本語になるかを確かめます。' }] },
      { h: '設問の型と答え方', t: '高校入試の長文問題は、だいたい決まった型で出ます。型ごとに答え方を知っておくと、迷う時間が減ります。\n【内容一致】…本文の内容に合う文を選ぶ。選択肢の主語・数字・時間・否定(not)を、本文の該当箇所と1つずつ照らし合わせます。本文の語句を別の言い方に言いかえた選択肢が正解になることが多いです。\n【英問英答】…英語の質問に英語で答える。Did 〜? には Yes, he did. / No, he didn\'t.、What 〜? には主語と動詞のある文で答えます。質問の時制に答えをそろえることが大切です。\n【空所補充・文の挿入】…空所の前後のつながり(つなぎことば・指示語)から入るものを決めます。\n【理由を答える】…本文の because や so の前後に答えがあることが多いです。日本語で答えるときは文末を「〜から。」にします。\n【タイトル・主題を選ぶ】…各段落のトピック・センテンスを集めて、全体に共通する内容を選びます。一部の段落だけの内容は不正解です。',
        key: '内容一致は主語・数字・否定を照合。英問英答は質問と時制をそろえる。理由は「〜から。」で答える。',
        ex: [{ q: '本文と質問を読み、英語で答えよう。\n本文:Yuki went to the library after school yesterday. She read a book about space there.\n質問:What did Yuki do at the library?', hint: '質問の時制(did)に注目し、主語と動詞のある文で答えましょう。', steps: ['質問は「ユキは図書館で何をしましたか」。did なので過去の文で答える。', '本文の2文目に「そこで(図書館で)宇宙についての本を読んだ」とある。', '主語 Yuki は代名詞 She にする。', '動詞は過去形 read を使い、She read a book about space. とする。'], a: 'She read a book about space.', check: '時制が過去になっているか、主語を代名詞にしたか、ピリオドがあるかを確かめます(read の過去形は read で、つづりは同じです)。' }] },
      { h: '入試本番の読み方の手順', t: '長文問題は配点が大きく、時間もかかります。本番であわてないために、読む手順を決めておきましょう。\n①【設問を先に見る】…何を探しながら読むかを決めます。質問に出てくる人名や数字に丸をつけておきます。\n②【タイトル・注・図表を見る】…本文の下にある語注(*の語の意味)や図表は大きなヒントです。読む前に目を通します。\n③【段落ごとに要点をつかむ】…各段落の最初の文を中心に読み、余白に日本語で一言メモを書きます(例:「第2段落=問題点」)。\n④【答えの根拠に線を引く】…設問に関係する部分を見つけたら線を引き、選択肢と照らし合わせます。\n⑤【知らない単語で止まらない】…前後の文脈やつなぎことばから意味を予想して、先に進みます。1語分からなくても、段落の主題が分かれば多くの問題は解けます。',
        key: '設問を先に見る→注・図表を確認→段落ごとに要点メモ→根拠に線→知らない語で止まらない。' }
    ],
    faq: [['知らない単語がたくさん出てきて、読む気がなくなります。', '入試の長文は、すべての単語を知っていなくても解けるように作られています。むずかしい語には注がつき、残りは前後の文から意味を予想できます。「名詞らしい」「よい意味らしい」程度に予想して先に進みましょう。'], ['本文を全部日本語に訳してから問題を解くべき?', '時間が足りなくなるのでおすすめしません。設問に関係する部分だけをていねいに読み、ほかの部分は要点をつかむ読み方にすると、時間内に解き終えられます。'], ['内容一致で、2つの選択肢が両方正しく見えるときは?', '本文に【はっきり書かれているか】で判断します。本文から「たぶんそうだろう」と想像しないと選べないものは不正解です。数字・主語・否定語がずれていないかも確かめましょう。']],
    terms: [['トピック・センテンス', '段落の最初に置かれ、その段落の主題を示す文'], ['サポーティング・センテンス', '主題を支える理由・具体例・説明の文'], ['つなぎことば', 'however・for example・so など、文と文の関係を示す語句'], ['指示語', 'it・they・this など、前に出た内容を指す語'], ['内容一致', '本文の内容に合う選択肢を選ぶ設問'], ['英問英答', '英語の質問に英語で答える設問'], ['言いかえ(パラフレーズ)', '同じ内容を別の語句で表すこと。正解の選択肢によく使われる']],
    miss: ['本文と同じ単語が入っている選択肢を、すぐ正解にしてしまう。同じ語を使って内容を少し変えたひっかけが多いので、主語・数字・否定まで照らし合わせて防ぐ。', 'for example の後ろの具体例を、筆者の主張だと思ってしまう。例は主張を支える材料と意識し、主張は例の前後のまとめの文から探す。', '指示語の答えを、指示語より後ろから探してしまう。指示語はふつう前の内容を指すので、まず直前の文を確認する。', '英問英答で Did 〜? に Yes, he does. と時制をずらす。質問の助動詞(do/does/did)を答えでもそのまま使う。'],
    sum: ['英語の段落は、最初のトピック・センテンスで主題を示し、後ろで理由や例を加える。', 'however の後ろは筆者の言いたいこと、for example の後ろは具体例、so の後ろは結論。', '指示語は直前から探し、候補を当てはめて意味が通るか読み直す。', '内容一致は主語・数字・否定を照合し、言いかえに注意する。英問英答は時制をそろえる。', '本番は「設問を先に→注・図表→段落ごとにメモ→根拠に線→知らない語で止まらない」。'],
    next: '読んだ内容について自分の考えを書く力をつけるため、「英作文(e_write)」へ進みましょう。'
  };

  // ===== 中学英語:英作文 =====
  L.e_write = {
    goal: '条件英作文の条件を正確に読み取り、「意見→理由2つ→まとめ」の型で、文法のミスが少ない英文を書けるようになる。',
    intro: '英作文で点が取れない原因は、「むずかしい表現を知らないこと」ではなく、「条件を守っていない」「簡単な文法でミスをしている」ことがほとんどです。採点する人が見ているのは、言いたいことが正しい英語で伝わるかどうかです。この単元では、どんなテーマにも使える書き方の型と、減点されやすいミスの防ぎ方を身につけます。',
    pre: '英語の文には、必ず【主語と動詞】が必要です。日本語では「サッカーが好きです」と主語を省けますが、英語では I like soccer. のように主語 I を書かなければなりません。\n主語が3人称単数(he・she・it・ケンなど)で現在の文なら、一般動詞に【s(es)】をつけます。例:She likes music.\n【不定詞】(to＋動詞の原形)と【動名詞】(動詞の〜ing)は、どちらも「〜すること」を表せます。ただし、want・hope・decide の後ろは不定詞、enjoy・finish・stop の後ろは動名詞、like・start は両方とれる、というように動詞によって決まっています。\n比較の文(〜er than / the 〜est / more 〜 than)は、意見文で「AよりBのほうがよい」と述べるときによく使います。例:I think reading books is more useful than watching TV.',
    secs: [
      { h: '条件を読み取ることがいちばん大事', t: 'なぜ条件がそれほど大切なのでしょうか。英作文の採点では、まず「条件を満たしているか」を確かめ、満たしていなければ内容がよくても大きく減点されるからです。\n高校入試でよく出る条件:【語数】(「20語以上」「25〜35語」)、【文の数】(「3文以上」)、【内容】(「理由を2つ書く」「賛成か反対かを明らかにする」)、【使う語】(「because を使って」)など。\n書く前に、問題文の条件すべてに線を引き、番号をつけましょう。書き終わったら、番号ごとにチェックします。\n語数の数え方:単語ごとに1語と数え、短縮形(don\'t・I\'m)は1語、ピリオドやコンマなどの符号は数えないのが一般的です。問題に数え方の指示があれば、それに従います。\n「20語以上」なら、20語ちょうどではなく、少し余裕をもって25語前後を目安にすると安全です。',
        key: '書く前に条件すべてに線を引いて番号をつけ、書いた後に番号ごとに確かめる。',
        ex: [{ q: '次の英文は何語?(短縮形は1語、符号は数えない)\nI\'m going to visit my grandfather this weekend.', hint: '1語ずつ指で区切って数えましょう。', steps: ['I\'m / going / to / visit / my / grandfather / this / weekend と区切る。', 'I\'m は短縮形なので1語と数える。', 'ピリオドは数えない。', '合計すると8語。'], a: '8語', check: 'もう一度、逆から数えて同じ数になるか確かめます。' }] },
      { h: '意見を書く型:意見→理由→まとめ', t: '「あなたは〜に賛成ですか」「〜についてあなたの考えを書きなさい」という問題は、次の型にあてはめると、ほとんどのテーマで書けます。\n①【意見】I think (that) 〜. / I agree with 〜. / I don\'t agree with 〜.(私は〜だと思います/〜に賛成です/反対です)\n②【理由の予告】I have two reasons.(理由は2つあります)\n③【理由1】First, 〜.(第一に)\n④【理由2】Second, 〜.(第二に)/ Also, 〜.(また)\n⑤【まとめ】For these reasons, I think 〜.(これらの理由から、私は〜だと思います)\n作例:I think students should read books every day. I have two reasons. First, we can learn many new words. Second, we can learn about other people\'s ideas. For these reasons, I think reading every day is important.\n訳:私は、生徒は毎日本を読むべきだと思います。理由は2つあります。第一に、新しい言葉をたくさん学べます。第二に、ほかの人の考えを知ることができます。これらの理由から、毎日読書をすることは大切だと思います。',
        key: '型:I think 〜. → I have two reasons. → First, 〜. → Second, 〜. → For these reasons, 〜.',
        ex: [{ q: '「夏と冬のどちらが好きか」について、意見の文と理由の文を1文ずつ英語で書こう。', hint: 'まず立場を決め、理由は because を使って1文にしてもよいです。', steps: ['立場を1つに決める(ここでは夏とする)。', '意見の文:I like summer better than winter.(冬より夏のほうが好きです)', '理由を、知っている単語で書ける内容にする(海で泳げる)。', '理由の文:I like summer because I can swim in the sea.(海で泳げるので夏が好きです)'], a: '(解答例)I like summer better than winter. I like summer because I can swim in the sea.', check: '主語と動詞があるか、better than の比較の形が正しいか、because の後ろが主語＋動詞の文になっているかを確かめます。' }] },
      { h: '書ける英語で書く:日本語を言いかえる', t: '英作文では、日本語で考えた内容をそのまま英語にしようとすると、知らない単語や複雑な文が必要になって手が止まります。そこで、【自分が書ける英語】に合わせて、内容を言いかえるのがコツです。\n例:「地域の活性化につながる」→「町の人がもっと元気になる」→ People in the town will be happier.\n例:「健康を維持できる」→「元気でいられる」→ We can stay healthy. / 「体によい」→ It is good for our health.\nむずかしい単語を1つ使うより、知っている単語で正しく書くほうが高く評価されます。つづりに自信のない単語は、別の言い方に変えましょう。\n使い回しのきく表現:It is fun to 〜.(〜するのは楽しい)、It is important to 〜.(〜することは大切だ)、〜 is good for 〜.(〜は〜によい)、We can 〜.(〜できる)、I want to 〜.(〜したい)。',
        key: '日本語をそのまま訳さず、知っている単語で書ける内容に言いかえる。正しさが最優先。',
        ex: [{ q: '「インターネットは情報収集に役立つ」を、中学で習う語だけで英語にしよう。', hint: '「情報収集」を「たくさんのことを調べる」くらいの言い方にしてみましょう。', steps: ['「情報収集に役立つ」を「いろいろなことを簡単に調べられる」と言いかえる。', '主語は We、動詞は can find を使う。', 'We can find a lot of information on the Internet. とする。', '「簡単に」を入れるなら easily を文末に置く。'], a: '(解答例)We can find a lot of information on the Internet easily.', check: 'information は数えられない名詞なので s をつけません(× informations)。冠詞や複数形のつけ方も確かめます。' }] },
      { h: '減点されやすいミス(1)文の形', t: '採点で減点されるミスの多くは、中学1・2年で習った基本文法のミスです。特に多いものを確認しましょう。\n【be動詞と一般動詞を重ねる】× I am like music. → ○ I like music. / × I am agree. → ○ I agree.\n【3単現の s を忘れる】× My brother play tennis. → ○ My brother plays tennis.\n【主語を書き忘れる】× Is very fun. → ○ It is very fun.\n【because だけの文】× I like dogs. Because they are cute. → ○ I like dogs because they are cute. 理由は主張の文とつなげて1文にします。\n【語順】× I very like music. → ○ I like music very much. very much は文の終わりに置きます。',
        key: '主語＋動詞はあるか、be動詞と一般動詞を重ねていないか、3単現の s、because だけの文になっていないか。',
        ex: [{ q: '次の英文の誤りを直そう。\n(1) I am agree with your idea.\n(2) My sister like cats. Because they are cute.', hint: '(1)は動詞の数、(2)は3単現と because の使い方を見ましょう。', steps: ['(1) agree は一般動詞なので am は不要。I agree with your idea. とする。', '(2) 主語 My sister は3人称単数なので like を likes にする。', '(2) Because 〜. だけの文は不完全なので、前の文とつなげて1文にする。', '(2) My sister likes cats because they are cute. とする。'], a: '(1) I agree with your idea. (2) My sister likes cats because they are cute.', check: '直した文を声に出して読み、主語と動詞が1組ずつそろっているかを確かめます。' }] },
      { h: '減点されやすいミス(2)語の形と見直し', t: '文の形が正しくても、語の形のミスで減点されることがあります。\n【名詞の複数形と冠詞】× I have many friend. → ○ I have many friends. / × I want dog. → ○ I want a dog. 数えられる名詞は、1つなら a(an)、2つ以上なら複数形にします。\n【動名詞と不定詞】× I enjoy to swim. → ○ I enjoy swimming. / × I want playing. → ○ I want to play.\n【時制】過去のことを書くときは、すべての動詞を過去形にそろえます。Last summer, I go to Okinawa. → Last summer, I went to Okinawa.\n【大文字・符号】文の最初の文字と I は大文字。文の終わりにピリオド(疑問文なら?)をつけます。\n書き終わったら、①条件、②主語と動詞、③3単現の s と時制、④複数形と冠詞、⑤つづりと大文字・ピリオド、の順に見直しましょう。',
        key: '見直しの順:条件→主語と動詞→3単現・時制→複数形・冠詞→つづり・大文字・ピリオド。' }
    ],
    faq: [['むずかしい単語を使ったほうが点が高くなる?', '高校入試の英作文では、むずかしい語よりも、条件を守り、正しい英語で、内容が伝わることが評価されます。つづりや使い方に自信のない語は、知っている語に言いかえるほうが安全です。'], ['賛成と反対、どちらの立場で書くほうがいいの?', 'どちらでも点数は変わりません。【理由を英語で書きやすいほう】を選びましょう。自分の本当の考えとちがっても、書きやすい立場を選んでかまいません。'], ['語数が足りないときは、どうすればいい?', '理由に具体例を1文加えるのがおすすめです。For example, 〜. で自分の体験を書くと、内容も深まり語数も増えます。同じ文のくり返しで語数をかせぐのはやめましょう。']],
    terms: [['条件英作文', '語数・文数・内容などの条件にしたがって書く英作文'], ['語数', '英文の単語の数。短縮形は1語、符号は数えないのが一般的'], ['I think (that) 〜.', '「私は〜だと思います」と意見を示す表現'], ['First, / Second,', '「第一に/第二に」と理由を順に並べる表現'], ['For these reasons,', '「これらの理由から」とまとめる表現'], ['言いかえ', '書けない日本語を、知っている英語で書ける内容に変えること']],
    miss: ['条件(語数・理由の数)を読み落とす。書く前に条件すべてに線を引き、書いた後に1つずつチェックして防ぐ。', 'I am like 〜. / I am agree. のように be動詞と一般動詞を重ねる。「動詞は1文に1つ(助動詞は別)」と確認して防ぐ。', 'Because 〜. だけの文を書く。because は主張の文とつないで1文にする。', 'enjoy to 〜 / want 〜ing のように、動詞の後ろの形をまちがえる。enjoy・finish は〜ing、want・hope は to 〜、と組で覚える。', '過去の体験を書くのに現在形が混ざる。体験を書いた部分の動詞をすべて確認して、過去形にそろえる。'],
    sum: ['書く前に条件すべてに線を引き、書いた後に1つずつ確かめる。語数は短縮形1語・符号は数えない。', '意見文の型:I think 〜. → I have two reasons. → First, 〜. → Second, 〜. → For these reasons, 〜.', '日本語をそのまま訳さず、知っている語で書ける内容に言いかえる。', 'be動詞と一般動詞の重ね、3単現の s、because だけの文、enjoy＋〜ing に注意する。', '見直しは「条件→主語と動詞→3単現・時制→複数形・冠詞→つづり・大文字・ピリオド」。'],
    next: '英作文の型は、長文の内容について意見を書く問題にも使えます。「長文読解(e_read)」で読んだ内容に、意見を書く練習をしてみましょう。'
  };

  var KOSEI = '<svg viewBox="0 0 220 150" class="lz-fig" role="img" aria-label="説明文の基本の構成。序論で話題や問いを示し、本論で例や理由を挙げて説明し、結論でまとめと主張を述べる"><rect x="5" y="40" width="62" height="40" class="bx"/><rect x="79" y="40" width="62" height="40" class="bx"/><rect x="153" y="40" width="62" height="40" class="bx"/><line x1="67" y1="60" x2="79" y2="60" class="ax"/><line x1="141" y1="60" x2="153" y2="60" class="ax"/><text x="40" y="24">説明文の基本の構成</text><text x="25" y="64">序論</text><text x="99" y="64">本論</text><text x="173" y="64">結論</text><text x="25" y="100">話題</text><text x="99" y="100">説明</text><text x="168" y="100">まとめ</text><text x="14" y="116">問いかけ</text><text x="88" y="116">例・理由</text><text x="173" y="116">主張</text></svg>';

  // ===== 中学国語:説明的文章 =====
  L.j_setsumei = {
    goal: '説明的文章の段落の役割と段落どうしの関係をつかみ、接続語・指示語を手がかりにして、筆者の主張と要旨を正確に答えられるようになる。',
    intro: '説明的文章(説明文・論説文)の問題は、「なんとなく読んで、なんとなく選ぶ」と点数が安定しません。でも、文章には設計図があります。家に玄関・部屋・屋根があるように、文章にも「話題を示す段落」「例を挙げる段落」「まとめる段落」があります。この単元では、設計図を見ぬいて、筆者がいちばん言いたいことをつかむ読み方を練習します。',
    pre: '【説明的文章】は、事実や筆者の考えを、読む人に分かりやすく伝えるための文章です。説明文(事実を説明する)と論説文(筆者の意見を述べる)があります。\n【形式段落】は1字下げで始まるまとまり、【意味段落】は内容が同じ形式段落をまとめた大きなまとまりです。設問では、段落に①②③…と番号がついていることが多いです。\n【接続語】は、前と後の関係を表す語です。順接(だから・そのため)、逆接(しかし・ところが)、並立・累加(また・さらに)、説明・補足(つまり・なぜなら)、例示(たとえば)、転換(さて・ところで)などがあります。\n【指示語】(これ・それ・この・その・このような)は、ふつう前に書かれた内容を指します。\nこの単元で読む例文は、すべてこのアプリで作った短い【作例】です。',
    secs: [
      { h: '序論・本論・結論と、主張の位置', t: '説明的文章の多くは、【序論・本論・結論】の3つの部分でできています。なぜこの形が多いかというと、「何の話か→くわしい説明→だから何が言えるか」の順に読むと、読む人が理解しやすいからです。\n【序論】…話題を示したり、「〜だろうか」と問いかけたりします。\n【本論】…具体例・理由・データなどを使って、くわしく説明します。\n【結論】…本論をまとめ、筆者の主張を述べます。序論の問いかけへの答えになっていることが多いです。\n主張がどこにあるかで、文章の型を分けることもあります。最初にあるのが【頭括型】、最後にあるのが【尾括型】、最初と最後の両方にあるのが【双括型】です。\n入試問題では、序論の問いかけと結論の答えを組にして見つけることが、要旨をつかむ近道になります。',
        key: '序論(話題・問い)→本論(例・理由)→結論(まとめ・主張)。問いかけと答えを組で探す。',
        fig: KOSEI,
        ex: [{ q: '作例の文章の型を答えよう。\n「①なぜ、日本では昔から木の家が多く建てられてきたのだろうか。②日本は森林が多く、木材が手に入りやすかった。③また、木は湿気を吸ったりはき出したりするので、蒸し暑い夏にも過ごしやすい。④このように、日本の木の家は、自然の条件に合った住まいなのである。」', hint: '筆者の考えがまとめて書かれているのは、どの段落でしょうか。', steps: ['①は「〜だろうか」という問いかけで、話題を示す序論。', '②③は、木の家が多い理由を挙げている本論。', '④は「このように」で②③をまとめ、筆者の考えを述べる結論。', '主張は最後の④にだけ書かれている。'], a: '尾括型', check: '①は問いかけで、主張そのものではありません。最初に主張がないので頭括型・双括型ではないと確かめられます。' }] },
      { h: '段落の役割を見分ける', t: '入試では「第③段落の役割として最も適切なものを選びなさい」という問題がよく出ます。段落の役割は、段落の【最初の語】と【最後の文】を見ると分かることが多いです。\n【話題の提示・問題提起】…「〜について考えてみたい」「〜だろうか」。文章の入り口です。\n【具体例】…「たとえば」「実際に」で始まることが多い。前の段落の考えを、身近な例で分かりやすくします。\n【理由・根拠】…「なぜなら」「〜からだ」。主張がなぜ正しいのかを支えます。\n【反論の想定と再反論】…「確かに〜。しかし〜」「もちろん〜。だが〜」。反対の考えを一度認めてから、自分の主張を強めます。\n【まとめ・主張】…「このように」「つまり」「〜のではないだろうか」「〜べきだ」。文章のゴールです。',
        key: '段落の役割は「最初の語」と「最後の文」で見分ける。たとえば=具体例、確かに〜しかし=反論への答え、このように=まとめ。',
        ex: [{ q: '作例の②段落の役割として最も適切なものを選ぼう。\n「①ごみを減らすには、一人ひとりの工夫が欠かせない。②たとえば、買い物にマイバッグを持っていけば、レジ袋のごみは出ない。」\nア 新しい話題を示している。 イ ①の内容を具体例で説明している。 ウ ①と反対の意見を述べている。 エ 文章全体の結論を述べている。', hint: '②の最初の語に注目しましょう。', steps: ['②は「たとえば」で始まっている。', '「たとえば」は例示の接続語で、前の内容の具体例が後に来る。', '②のマイバッグの話は、①の「一人ひとりの工夫」の具体的な例になっている。'], a: 'イ', check: '②を消しても①の考えは残り、②だけでは主張にならないことから、②は①を支える具体例だと確かめられます。' }] },
      { h: '接続語で段落どうしの関係をつかむ', t: '接続語は、文章の道しるべです。接続語を見れば、前と後がどんな関係かが分かり、読みのスピードも正確さも上がります。\n【逆接】(しかし・だが・ところが・けれども)…後ろに前と反対の内容が来ます。説明的文章では、逆接の後ろに筆者の言いたいことが来ることがとても多いです。\n【順接】(だから・したがって・そのため)…前が理由・原因、後ろが結果・結論です。\n【説明・言いかえ】(つまり・すなわち・要するに)…前の内容を短く言いかえたり、まとめたりします。後ろが大事なことが多いです。\n【並立・累加】(また・さらに・そのうえ)…前と同じ方向の内容を加えます。理由が2つ以上並ぶときによく使われます。\n空所に接続語を入れる問題では、空所の前後の文を1文ずつ取り出して、「同じ方向か・反対か・理由と結果か・言いかえか」を判断します。',
        key: '逆接(しかし)と言いかえ(つまり)の後ろには、筆者の言いたいことが来やすい。',
        ex: [{ q: '( )に入る接続語を選ぼう。\n作例「スマートフォンは、いつでもどこでも調べものができる便利な道具だ。(   )、使いすぎると、自分で考える時間が減ってしまうおそれもある。」\nア だから イ しかし ウ たとえば エ つまり', hint: '前の文は「よい点」、後ろの文は何を述べているでしょうか。', steps: ['前の文はスマートフォンの便利さ(よい点)を述べている。', '後ろの文は使いすぎたときのおそれ(よくない点)を述べている。', 'よい点とよくない点は反対の方向なので、逆接の接続語が入る。'], a: 'イ しかし', check: '「だから」を入れると「便利だから考える時間が減る」となり、理由と結果の関係として不自然です。' }] },
      { h: '指示語の内容を答える', t: '指示語の問題は、正しい手順で解けば確実に得点できます。\n手順①:指示語より【前】を探します。ふつうは直前の文や、同じ文の前の部分です。\n手順②:見つけた内容を、指示語の位置に【当てはめて】読みます。意味が通れば正解です。\n手順③:答えの文末を、問題の形に合わせて整えます。「何を指しますか」なら「〜こと。」、「どのようなことですか」なら「〜ということ。」とまとめます。\n「このような」「こうした」のように、前の段落全体の内容をまとめて指す指示語もあります。その場合は、前の段落の要点を短くまとめて答えます。\n抜き出し問題では、字数の指定に合う部分を探し、句読点も1字に数えるかどうか、問題の指示を確かめましょう。',
        key: '指示語は前を探す→当てはめて読む→文末を「〜こと。」に整える。',
        ex: [{ q: '作例の「それ」が指す内容を答えよう。\n「祖父は毎朝、庭の花に水をやる。それが、祖父の一日の始まりなのだ。」', hint: '「それ」の前の文から探し、当てはめてみましょう。', steps: ['「それ」より前を探すと、直前の文「祖父は毎朝、庭の花に水をやる」がある。', '「それ」の位置に当てはめる:「毎朝、庭の花に水をやることが、祖父の一日の始まりなのだ」。', '意味が通るので、この内容が答え。', '文末を「〜こと。」に整える。'], a: '(祖父が)毎朝、庭の花に水をやること。', check: '当てはめた文が自然な日本語として読めることで、指す内容が正しいと確かめられます。' }] },
      { h: '要旨と筆者の主張のまとめ方', t: '【要旨】は、文章の中で筆者がいちばん伝えたい中心の考えです。文章全体を順に短くした【要約】とはちがい、具体例は入れません。\nまとめる手順:①各段落の役割を見分け、具体例の段落をいったん外す。②「このように」「つまり」「〜べきだ」「〜が大切だ」「〜のではないだろうか」などの文を探す。③序論の問いかけと、結論の答えを組にする。④1〜2文、指定があれば字数に合わせてまとめる。\n記述問題では、本文の言葉を使ってまとめるのが基本です。自分の意見や、本文にない言葉を加えてはいけません。\n選択肢の問題では、「本文の一部分だけの内容」「本文と逆の内容」「言いすぎ(必ず・すべて)」の選択肢を消していきます。\n筆者の主張は、ときに「〜のではないだろうか」という問いかけの形で書かれます。これは「〜だと思う」という意味の、やわらかい主張の言い方です。',
        key: '要旨=具体例を外し、問いかけと答えを組にして、本文の言葉で1〜2文にまとめる。',
        ex: [{ q: '作例の要旨を、40字程度でまとめよう。\n「①私たちは、失敗をできるだけさけようとする。②しかし、発明家の多くは、何百回もの失敗を重ねてから成功している。③失敗によって、どの方法がうまくいかないかが分かるからだ。④失敗は、成功に近づくための大切な手がかりなのではないだろうか。」', hint: '②は具体例、③は理由です。主張は④にあります。', steps: ['①は話題(私たちは失敗をさけようとする)。', '②は発明家の具体例、③は失敗が役に立つ理由。', '④の「〜のではないだろうか」が筆者の主張。', '主張に理由をそえて、本文の言葉でまとめる。'], a: '(解答例)失敗によってうまくいかない方法が分かるので、失敗は成功に近づくための大切な手がかりである。(45字)', check: '発明家の例を入れていないか、本文にない自分の意見を加えていないか、字数が指定に近いかを確かめます。' }] }
    ],
    faq: [['要旨を書く問題で、本文の言葉を使わずに自分の言葉で書いてもいい?', '基本は本文の言葉を使いましょう。採点では、本文中の大事な言葉(キーワード)が入っているかを見ることが多いからです。ただし、長い部分はつなげやすいように少し言いかえてかまいません。'], ['筆者の主張が「〜のではないだろうか」と疑問の形なのはなぜ?', '断定するより、読む人に「たしかにそうかもしれない」と考えてもらうための、やわらかい言い方です。疑問の形でも、中身は筆者の主張なので、要旨の中心になります。'], ['段落の役割を選ぶ問題で、2つの選択肢で迷います。', 'その段落の【前後の段落】との関係を確かめましょう。前の段落の例なのか、理由なのか、反対の考えなのかは、つながりの中でしか決まりません。接続語と、段落の最後の文が手がかりです。']],
    terms: [['序論・本論・結論', '話題の提示、くわしい説明、まとめと主張という文章の3つの部分'], ['頭括型・尾括型・双括型', '主張が最初・最後・最初と最後の両方にある文章の型'], ['要旨', '筆者がいちばん伝えたい中心の考え'], ['要約', '文章全体の内容を、順序にそって短くまとめたもの'], ['逆接', '前と反対の内容が後に来るつながり(しかし・ところが)'], ['問題提起', '「〜だろうか」と問いかけて、文章の話題を示すこと'], ['作例', 'この単元の練習のために作った例文']],
    miss: ['具体例の段落の内容を、要旨に入れてしまう。要旨では例を外すと決め、「たとえば」の段落にはかっこをつけて読む。', '「確かに〜」の部分を筆者の主張だと思ってしまう。「確かに」は反対意見を一度認める言い方で、主張は「しかし」の後ろにあると確認する。', '指示語の答えを、指示語の後ろから探してしまう。指示語はふつう前を指すので、まず直前を探し、当てはめて確かめる。', '選択肢の「必ず」「すべて」などの言いすぎに気づかない。本文が「〜こともある」なのに選択肢が断定していないか、程度を表す言葉を照らし合わせる。'],
    sum: ['説明的文章は序論(話題・問い)→本論(例・理由)→結論(まとめ・主張)。', '段落の役割は、最初の語(たとえば・確かに・このように)と最後の文で見分ける。', '逆接(しかし)と言いかえ(つまり)の後ろには、筆者の言いたいことが来やすい。', '指示語は前を探し、当てはめて読み、「〜こと。」に整える。', '要旨は、具体例を外し、問いかけと答えを組にして本文の言葉でまとめる。'],
    next: '文学的文章の読み方を学ぶため「文学的文章(小説)の読解(j_shosetsu)」へ。自分の考えを書く力は「作文・条件作文(j_sakubun)」で身につけましょう。'
  };

  // ===== 中学国語:小説 =====
  L.j_shosetsu = {
    goal: '小説の場面をつかみ、登場人物の心情とその変化を、行動・会話・表情・情景を根拠にして説明でき、表現技法の効果も答えられるようになる。',
    intro: '小説の問題で「主人公の気持ちを答えなさい」と言われると、「人によって感じ方がちがうのでは?」と思うかもしれません。でも、入試の答えは必ず本文の中に【根拠】があります。人の気持ちは、顔色や行動、言葉づかいに表れますね。小説も同じで、作者は気持ちを直接書かずに、行動や風景を使って伝えます。この単元では、その手がかりの見つけ方を練習します。',
    pre: '【文学的文章】は、物語や体験を通して、人の気持ちや生き方を伝える文章です。小説・物語・随筆などがあります。小説を書いた人を【作者】といいます。\n小説の中で語っている人を【語り手】といいます。「ぼく」「私」が語る文章と、登場人物を外から「彼は」と語る文章があります。\n【会話文】はかぎかっこ(「」)で書かれた登場人物の言葉、【地の文】はそれ以外の説明の部分です。\n気持ちを表す言葉(心情語)には、うれしい・悲しいのほかに、くやしい・照れくさい・気まずい・誇らしい・ほっとする・後ろめたい、などがあります。答えを書くときに使えるよう、少しずつ増やしていきましょう。\nこの単元で読む例文は、すべてこのアプリで作った短い【作例】です。',
    secs: [
      { h: '場面をつかむ:時・場所・人物', t: 'なぜ最初に場面をつかむのでしょうか。同じ「泣いた」という行動でも、卒業式の場面なのか、試合に負けた場面なのかで、気持ちはまったくちがうからです。\n場面は、【いつ(時)・どこで(場所)・だれが(人物)】の3つでつかみます。\n時間がとんだり(「その夜」「三年後」)、場所が変わったり、新しい人物が登場したりしたところで、場面が変わります。入試では「この文章を二つの場面に分けるとき、後半はどこから始まるか」という問題も出ます。\n【回想】にも注意しましょう。「あのときのことを思い出す」のように、過去の場面が途中に入ることがあります。回想の部分では、今の気持ちと昔の気持ちを区別して読みます。\n人物については、名前だけでなく、主人公との関係(友だち・きょうだい・先生)も押さえます。',
        key: '場面は時・場所・人物でつかむ。時間・場所・人物が変わったところが場面の切れ目。',
        ex: [{ q: '作例の場面(時・場所・人物)を答えよう。\n「夏休み最後の日の夕方、ぼくは姉と二人で、川原の土手に座っていた。」', hint: '時・場所・人物を、本文の言葉で1つずつ抜き出しましょう。', steps: ['時:「夏休み最後の日の夕方」。', '場所:「川原の土手」。', '人物:「ぼく」と「姉」の二人。'], a: '時=夏休み最後の日の夕方、場所=川原の土手、人物=ぼくと姉', check: '「夏休み最後の日」という時の設定から、楽しい時間が終わるさびしさのような気持ちが描かれるのでは、と予想しながら読むと、心情の読み取りにもつながります。' }] },
      { h: '心情は「きっかけ→気持ち→行動」で読む', t: '小説では、「悲しかった」のように気持ちが直接書かれることは少なく、多くは【行動・表情・会話・しぐさ】で表されます。\nそこで、【できごと(きっかけ)→ 気持ち → 行動・表情・会話】という流れを考えます。本文に書かれているのは、たいてい最初の「きっかけ」と最後の「行動」で、真ん中の「気持ち」を読み取るのが問題の中心です。\n例:先生にほめられた(きっかけ)→ うれしいけれど照れくさい(気持ち)→ 下を向いて、頭をかいた(行動)。\n行動の手がかりの例:うつむく(落ちこみ・気まずさ)、くちびるをかむ(くやしさ)、目をそらす(気まずさ・後ろめたさ)、胸をはる(誇らしさ)、肩の力がぬける(安心)。\n答えを書くときは、「〜ので(きっかけ)、〜という気持ち」の形にすると、根拠と気持ちの両方が入った答えになります。',
        key: '心情=「きっかけ」と「行動」の間にあるもの。答えは「〜ので、〜という気持ち」の形で書く。',
        ex: [{ q: '作例の「ぼく」の気持ちを説明しよう。\n「リレーのアンカーで、ぼくは最後に抜かれてしまった。みんなの『ドンマイ』という声に、ぼくはくちびるをかんで、うなずくことしかできなかった。」', hint: 'きっかけのできごとと、「くちびるをかんで」という行動に注目しましょう。', steps: ['きっかけ:アンカーで最後に抜かれてしまった。', '行動:くちびるをかんで、うなずくことしかできなかった。', 'くちびるをかむ → くやしさをこらえている。', 'みんなの声にうなずくだけ → 申しわけなさで、言葉が出ない。'], a: '(解答例)自分が抜かれたせいで負けてしまったので、くやしく、仲間に申しわけないという気持ち。', check: '答えに「抜かれた」というきっかけと、「くやしい・申しわけない」という気持ちの両方が入っているかを確かめます。' }] },
      { h: '心情の変化ときっかけ', t: '入試の小説問題でいちばん大切なのが、【心情の変化】です。物語の中で、人物の気持ちはできごとをきっかけに変わっていきます。\n読み方:①はじめの気持ち、②変化の【きっかけ】(人の言葉・できごと・気づき)、③変化した後の気持ち、の3つを整理します。\n変化の目印になる表現:「そのとき」「ふと」「はっとした」「初めて〜に気づいた」「いつの間にか」「〜が、うそのように消えていた」など。\n記述問題では、「はじめは〜だったが、〜をきっかけに、〜という気持ちに変わった」という形でまとめると、変化の流れがはっきりします。\n人物の変化を通して、作品全体が伝えようとしていること(【主題】)が見えてきます。たとえば「友だちとの関わりを通して、自分の弱さを受け入れる」などです。',
        key: '心情の変化は「はじめの気持ち→きっかけ→後の気持ち」の3点セットで整理する。',
        ex: [{ q: '作例の「私」の心情の変化を説明しよう。\n「ピアノの発表会の前、私は手がふるえて止まらなかった。そのとき、母が客席から小さく手をふってくれた。私は一つ深呼吸をして、いすに座った。」', hint: '「そのとき」が変化の目印です。前後で気持ちがどう変わったでしょう。', steps: ['はじめ:手がふるえて止まらない → とても緊張して不安な気持ち。', 'きっかけ:「そのとき」母が客席から手をふってくれた。', '後:深呼吸をしていすに座った → 落ち着きを取りもどし、弾く覚悟ができた。', '「はじめは〜だったが、〜をきっかけに、〜」の形でまとめる。'], a: '(解答例)はじめは緊張して不安だったが、母が手をふってくれたことをきっかけに落ち着きを取りもどし、演奏に向かう気持ちになった。', check: 'はじめ・きっかけ・後の3つがすべて答えに入っているかを確かめます。' }] },
      { h: '情景描写:風景に気持ちが重なる', t: '小説の風景や天気の書き方は、ただの背景ではありません。人物の気持ちに合わせて描かれることが多く、これを【情景描写】といいます。\nなぜ作者は情景を使うのでしょうか。「悲しかった」と直接書くより、「冷たい雨が窓をたたいていた」と書くほうが、読む人がその気持ちを深く感じられるからです。\n暗い気持ちの例:重い雲、冷たい雨、日が沈む、風が冷たい。\n明るい気持ちの例:青空が広がる、日が差しこむ、雨が上がる、新しい芽が出る。\n特に、物語の最後で雨が上がる・朝日が差すといった情景は、人物の気持ちが明るい方向へ変わったことを表すことが多いです。\n入試では「この情景描写は、人物のどのような気持ちを表しているか」という形で出題されます。情景の「明るさ・暗さ」と、その直前のできごとを結びつけて答えます。',
        key: '情景描写は人物の心情を映す。情景の明るさ・暗さを、直前のできごとと結びつけて読む。' },
      { h: '表現技法とその効果', t: '表現技法は、名前を答える問題と、【効果】を答える問題の両方が出ます。\n【比喩】…あるものを別のものにたとえる。「〜のように」を使う【直喩(明喩)】(雪のように白い)、使わない【隠喩(暗喩)】(君はぼくの太陽だ)、人でないものを人のように表す【擬人法】(風がささやく)。\n【倒置法】…ふつうの語順を入れかえて、前に出た部分を強める。「見つけた、あの手紙を。」\n【体言止め】…文を名詞(体言)で終えて、余韻を残したり印象を強めたりする。「空には一番星。」\n【反復】…同じ言葉をくり返して強める。「待った。待って、待ち続けた。」\n【擬音語・擬態語】…音や様子を表す言葉。「ドンドン」(音)、「そわそわ」(様子)。\n効果を答えるときは、「〜を強調している」「〜の様子を生き生きと伝えている」「〜の気持ちを印象づけている」のように、何をどう伝えているかまで書きます。',
        key: '直喩は「〜のように」あり、隠喩はなし。効果は「何を・どう伝えているか」まで答える。',
        ex: [{ q: '作例「教室は、試験の前の湖のように静まりかえっていた。」に使われている表現技法と、その効果を答えよう。', hint: '「〜のように」があるかどうかを確かめましょう。', steps: ['「湖のように」と「〜のように」を使ってたとえている。', '「〜のように」を使うたとえは直喩(明喩)。', '波の立たない湖にたとえることで、教室が物音ひとつしないほど静かな様子を表している。', 'その静けさから、生徒たちの緊張感も伝わる。'], a: '直喩(明喩)。教室が物音ひとつしないほど静かで、緊張した空気に包まれている様子を印象的に伝えている。', check: 'たとえているもの(教室)と、たとえに使ったもの(湖)の共通点(静けさ)を言えるかで確かめます。' }] }
    ],
    faq: [['気持ちを答える問題で、自分が感じたことを書いてはいけないの?', '入試の問題は「本文から読み取れる気持ち」を聞いています。自分ならどう感じるかではなく、本文の行動・会話・情景に根拠がある気持ちを答えます。根拠になる部分を指させるかどうかが、正しい答えの目安です。'], ['記述の答えで、気持ちを表す言葉が思いつきません。', '「くやしい」「申しわけない」「照れくさい」「誇らしい」「ほっとする」「後ろめたい」「もどかしい」など、心情語をノートにまとめて増やしておきましょう。「うれしい」「悲しい」だけでは、細かい気持ちが表せないことが多いです。'], ['選択肢の問題で、どれも少しずつ正しく見えます。', '選択肢を「きっかけ」と「気持ち」に分けて、それぞれ本文と照らし合わせましょう。気持ちは合っていてもきっかけがちがう、気持ちが強すぎる(本文はがっかりなのに選択肢は絶望)などの選択肢を消していきます。']],
    terms: [['場面', '時・場所・人物によってまとまる、物語の一区切り'], ['心情', '登場人物の気持ち'], ['情景描写', '人物の気持ちに合わせて、風景や天気を描くこと'], ['直喩(明喩)・隠喩(暗喩)', '「〜のように」を使うたとえ・使わないたとえ'], ['擬人法', '人でないものを、人のように表す技法'], ['倒置法・体言止め', '語順を入れかえて強める技法・名詞で文を終える技法'], ['主題', '作品を通して作者が描こうとした中心的な考えや思い'], ['回想', '過去のできごとを思い出す場面']],
    miss: ['本文に書かれていない気持ちを、自分の想像で答える。答えの根拠になる行動・会話・情景を、本文の中で必ず指させるか確かめる。', '心情の変化の問題で、変化した後の気持ちだけを書く。「はじめ→きっかけ→後」の3点がそろっているか見直す。', '直喩と隠喩を取りちがえる。「〜のように・〜みたいな」があれば直喩、なければ隠喩と、言葉の有無で判断する。', '表現技法の効果の問題で、技法の名前だけを書く。「何を強めているか・どんな様子を伝えているか」まで書く。'],
    sum: ['場面は時・場所・人物でつかみ、それが変わるところで場面が切りかわる。', '心情は「きっかけ→気持ち→行動」の真ん中。行動・表情・会話を根拠に読む。', '心情の変化は「はじめの気持ち→きっかけ→後の気持ち」で整理する。', '情景描写は人物の心情を映す。明るさ・暗さを、直前のできごとと結びつける。', '表現技法(直喩・隠喩・擬人法・倒置法・体言止め・反復)は、名前と効果をセットで答える。'],
    next: '昔の人が書いた物語や随筆の読み方を学ぶため「古典作品の読解(j_classic)」へ進みましょう。'
  };

  // ===== 中学国語:古典作品 =====
  L.j_classic = {
    goal: '高校入試によく出る古典作品(竹取物語・枕草子・平家物語・徒然草・おくのほそ道・論語)の作者・時代・ジャンルと、有名な一節の意味・内容を説明できるようになる。',
    intro: '古典は「昔の言葉だからむずかしい」と思われがちですが、入試に出る作品と場面はかなり決まっています。冒頭の一節や有名な場面を、意味と一緒に知っておくだけで、初めて読む文章でも内容がぐっとつかみやすくなります。この単元では、6つの作品について、「いつ・だれが・どんな作品か」と「有名な一節は何を言っているか」をセットで学びます。',
    pre: '古文は【歴史的仮名遣い】で書かれています。語の途中・終わりの「は・ひ・ふ・へ・ほ」は「わ・い・う・え・お」と読みます(例:いふ→いう、をかし→おかし)。「ゐ・ゑ・を」は「い・え・お」と読みます。\n【係り結び】は、文の中に「ぞ・なむ・や・か」があると文末が連体形に、「こそ」があると已然形に変わるきまりです。強調や疑問を表します。\n古文では主語が省略されることが多いので、「だれが」を補いながら読みます。また、今の言葉と意味がちがう【古語】(うつくし=かわいらしい、をかし=趣がある、あはれなり=しみじみと心が動く)に注意します。\n漢文は、中国の古い文章を日本語の語順で読めるようにしたものです。【返り点】(レ点・一二点)にしたがって読み、漢字かな交じりに直した文を【書き下し文】といいます。\n作品の時代は、古い順に【平安(竹取物語・枕草子)→鎌倉(平家物語・徒然草)→江戸(おくのほそ道)】です。論語は、古代中国の孔子の言葉をまとめたものです。',
    secs: [
      { h: '竹取物語:日本最古の物語', t: '【竹取物語】は、平安時代の初めごろに成立した物語で、作者は分かっていません。現存する日本最古の物語とされ、『源氏物語』の中でも「物語の出で来はじめの祖」(物語の始まりの祖先)とよばれています。\n冒頭:「今は昔、竹取の翁といふもの有りけり。野山にまじりて竹を取りつつ、よろづのことに使ひけり。名をば、さぬきのみやつことなむいひける。その竹の中に、もと光る竹なむ一筋ありける。あやしがりて寄りて見るに、筒の中光りたり。それを見れば、三寸ばかりなる人、いとうつくしうてゐたり。」\n現代語訳:今ではもう昔のことだが、竹取の翁という者がいた。野山に分け入って竹を取っては、いろいろなことに使っていた。名前を、さぬきのみやつこといった。その竹の中に、根もとが光る竹が一本あった。不思議に思って近寄って見ると、筒の中が光っている。それを見ると、三寸(約9cm)ほどの人が、とてもかわいらしい様子で座っていた。\n大事な古語:「あやし」=不思議だ、「うつくし」=かわいらしい、「ゐたり」=座っていた。「なむ〜ける」は係り結び(なむ→連体形)です。\nあらすじ:かぐや姫は美しく成長し、五人の貴公子の求婚にむずかしい課題(難題)を出してしりぞけ、帝の求婚も受け入れません。そして八月十五日の夜、月の都からのむかえとともに月へ帰っていきます。物語の最後には、富士山の名前の由来が語られます。',
        key: '竹取物語=平安初期・作者不明・現存最古の物語。「うつくし」=かわいらしい。',
        ex: [{ q: '「三寸ばかりなる人、いとうつくしうてゐたり。」を現代語に訳そう。', hint: '「ばかり」「いと」「うつくし」「ゐたり」の意味を1つずつ考えましょう。', steps: ['「三寸ばかりなる人」=三寸(約9cm)ほどの人。「ばかり」は「〜ほど・くらい」。', '「いと」=とても。', '「うつくしう」=かわいらしく(古語の「うつくし」は「かわいらしい」)。', '「ゐたり」=座っていた(「ゐる」は「座る・じっとしている」)。'], a: '三寸ほどの人が、とてもかわいらしい様子で座っていた。', check: '「うつくし」を今の「美しい」と訳していないか確かめます。小さな子どもへの「かわいらしい」という気持ちを表す語です。' }] },
      { h: '枕草子:「をかし」の随筆', t: '【枕草子】は、平安時代の中ごろに【清少納言】が書いた【随筆】です。随筆とは、見たこと・聞いたこと・感じたことを、思うままに自由に書いた文章です。清少納言は、一条天皇の中宮(きさき)である【定子】に仕えていました。\n冒頭:「春はあけぼの。やうやう白くなりゆく山ぎは、少しあかりて、紫だちたる雲の細くたなびきたる。夏は夜。月のころはさらなり。やみもなほ、蛍の多く飛びちがひたる。また、ただ一つ二つなど、ほのかにうち光りて行くもをかし。雨など降るもをかし。」\n現代語訳:春は明け方がよい。だんだん白くなっていく山ぎわの空が少し明るくなって、紫がかった雲が細くたなびいているのがよい。夏は夜がよい。月のころは言うまでもない。闇夜もやはり、蛍がたくさん飛びかっているのがよい。また、ほんの一つ二つなどが、かすかに光って飛んでいくのも趣がある。雨などが降るのも趣がある。\n続く部分では、【秋は夕暮れ】(からすがねぐらへ急ぐ様子や、雁が連なって小さく見える様子)、【冬はつとめて】(早朝。雪や霜、急いで火をおこして炭を運ぶ様子)がよいと述べています。\n大事な古語:「あけぼの」=夜がほのぼのと明けはじめるころ、「やうやう」=だんだん、「さらなり」=言うまでもない、「をかし」=趣がある、「つとめて」=早朝。枕草子は、明るく知的な美しさを表す「をかし」の文学といわれます。',
        key: '枕草子=平安中期・清少納言・随筆。春はあけぼの、夏は夜、秋は夕暮れ、冬はつとめて。',
        ex: [{ q: '『枕草子』で、清少納言が四季それぞれによいとした時間帯を、春から順に答えよう。', hint: '春は「あけぼの」です。夏・秋・冬はそれぞれ一日のどの時間帯でしょう。', steps: ['春は「あけぼの」(夜明けのころ)。', '夏は「夜」(月のころはもちろん、闇夜の蛍も)。', '秋は「夕暮れ」(からすや雁の様子)。', '冬は「つとめて」(早朝)。'], a: '春=あけぼの、夏=夜、秋=夕暮れ、冬=つとめて(早朝)', check: '「つとめて」を「努力して」と訳していないか確かめます。古語では「早朝」の意味です。' }] },
      { h: '平家物語:無常をえがく軍記物語', t: '【平家物語】は、鎌倉時代に成立した【軍記物語】(戦いをえがいた物語)で、作者ははっきりしていません。平家(平氏)一族が栄え、源氏との戦いに敗れてほろびていく様子をえがいています。【琵琶法師】が琵琶をひきながら語り伝えたことでも知られます。\n冒頭:「祇園精舎の鐘の声、諸行無常の響きあり。沙羅双樹の花の色、盛者必衰の理をあらはす。おごれる人も久しからず、ただ春の夜の夢のごとし。たけき者もつひには滅びぬ、ひとへに風の前の塵に同じ。」\n現代語訳:祇園精舎の鐘の音には、この世のすべてのものは移り変わるという響きがある。沙羅双樹の花の色は、勢いの盛んな者も必ず衰えるという道理を表している。おごり高ぶっている人も長くは続かない、ただ春の夜の夢のようにはかない。勇ましく強い者もついには滅びてしまう、まったく風の前の塵と同じだ。\n【諸行無常】=すべてのものは移り変わり、永遠に変わらないものはない、という仏教の考え。【盛者必衰】=勢いの盛んな者も必ず衰える。冒頭の文は、「祇園精舎の鐘の声」と「沙羅双樹の花の色」のように、形のそろった2つの句を並べる【対句】でできています。\n文体は、漢語と和語がまじった【和漢混交文】で、力強いリズムがあります。有名な場面に、那須与一が舟の上の扇を弓で射ぬく「扇の的」、熊谷直実が若い平敦盛を討つ「敦盛の最期」があります。',
        key: '平家物語=鎌倉・軍記物語・琵琶法師。テーマは諸行無常・盛者必衰。冒頭は対句。',
        ex: [{ q: '『平家物語』冒頭の「おごれる人も久しからず、ただ春の夜の夢のごとし」は、どのようなことを述べているか説明しよう。', hint: '「おごれる」「久しからず」「春の夜の夢」の意味を考えましょう。', steps: ['「おごれる人」=おごり高ぶっている人、権力をほこる人。', '「久しからず」=長くは続かない。', '「春の夜の夢のごとし」=春の夜に見る夢のように、短くはかない。', '全体として、権力をほこる者の栄えは長続きせず、はかないということを述べている。'], a: '権力をほこっておごり高ぶる人の栄えも長くは続かず、春の夜の夢のようにはかないということ。', check: '冒頭全体のテーマである「盛者必衰」(盛んな者も必ず衰える)と内容が合っているか確かめます。' }] },
      { h: '徒然草:兼好法師の随筆', t: '【徒然草】は、鎌倉時代の終わりごろに【兼好法師】(吉田兼好)が書いた【随筆】です。自然や人間、生き方について、するどい観察と考えを書きつづっています。『枕草子』、鴨長明の『方丈記』とあわせて、【日本三大随筆】とよばれます。\n序段:「つれづれなるままに、日暮らし、硯にむかひて、心にうつりゆくよしなしごとを、そこはかとなく書きつくれば、あやしうこそものぐるほしけれ。」\n現代語訳:することもなく退屈なのにまかせて、一日中、硯に向かって、心に浮かんでは消えていくとりとめもないことを、なんということもなく書きつけていると、妙にばかばかしい気持ちになってくる。\n大事な古語:「つれづれなり」=することがなく退屈だ、「日暮らし」=一日中、「よしなしごと」=とりとめもないこと。文末の「こそ〜けれ」は係り結び(こそ→已然形)です。\n有名な話「仁和寺にある法師」:年をとるまで石清水八幡宮にお参りしたことのなかった仁和寺の法師が、一人で歩いてお参りに出かけ、ふもとの極楽寺・高良などを拝んで、これで全部だと思いこんで帰ってきてしまいました。本当にお参りすべき八幡宮は山の上にあったのです。兼好法師は最後に「少しのことにも、先達はあらまほしき事なり」(ちょっとしたことにも、案内役はあってほしいものだ)と述べています。',
        key: '徒然草=鎌倉末期・兼好法師・随筆。「先達はあらまほしき事なり」=案内役はあってほしい。',
        ex: [{ q: '「仁和寺にある法師」の話で、法師が失敗した原因と、兼好法師の教訓を答えよう。', hint: '法師は一人で出かけ、山の上まで行きませんでした。', steps: ['法師は、だれにも聞かずに一人でお参りに出かけた。', 'ふもとの寺社だけを拝んで、目的の八幡宮(山の上)を拝まずに帰ってしまった。', '原因は、よく知っている人(案内役)がいなかったこと。', '兼好法師は「少しのことにも、先達はあらまほしき事なり」とまとめている。'], a: '原因:案内役がいないまま一人で出かけ、山の上の八幡宮を拝まずに帰ってきたこと。教訓:ちょっとしたことにも、案内役(先達)はあってほしいものだ。', check: '「あらまほし」は「あってほしい・望ましい」という意味です。教訓の訳が「案内役はいらない」と逆になっていないか確かめます。' }] },
      { h: 'おくのほそ道:芭蕉の紀行文', t: '【おくのほそ道】は、江戸時代の俳人【松尾芭蕉】が書いた【紀行文】(旅の記録)です。芭蕉は元禄二年(1689年)、門人の曾良とともに江戸を出発し、東北・北陸地方を旅して、美濃(今の岐阜県)の大垣まで歩きました。文章の中に俳句がちりばめられています。\n冒頭:「月日は百代の過客にして、行きかふ年もまた旅人なり。舟の上に生涯をうかべ、馬の口とらへて老いをむかふる者は、日々旅にして旅をすみかとす。古人も多く旅に死せるあり。」\n現代語訳:月日は永遠に旅を続ける旅人のようなものであり、来ては去っていく年もまた旅人である。舟の上で一生を過ごす船頭や、馬のくつわを取って年老いていく馬子は、毎日が旅であって、旅をすみかとしている。昔の人も、多くが旅の途中で亡くなっている。\n有名な句:平泉で、奥州藤原氏や源義経たちの昔をしのんでよんだ【夏草や兵どもが夢の跡】(季語:夏草・夏)。立石寺でよんだ【閑かさや岩にしみ入る蝉の声】(季語:蝉・夏)。【五月雨をあつめて早し最上川】(季語:五月雨・夏。五月雨は今の梅雨の長雨)。\n「夏草や」の「や」のように、句の中で感動を表して切れ目を作る言葉を【切れ字】といいます(や・かな・けり など)。',
        key: 'おくのほそ道=江戸・松尾芭蕉・紀行文。「夏草や兵どもが夢の跡」は平泉、季語は夏草(夏)。',
        ex: [{ q: '「夏草や兵どもが夢の跡」の季語・季節・切れ字を答え、句の内容を説明しよう。', hint: '「や」が切れ字です。「兵ども」はだれ、「夢」は何をたとえているでしょう。', steps: ['季語は「夏草」で、季節は夏。', '切れ字は「や」で、目の前の夏草への感動を表し、句に切れ目を作っている。', '「兵ども」は昔この地で戦った武士たち、「夢」は彼らの栄華や功名を求めた思い。', '昔の武士たちの栄華も今は消え、夏草がしげるばかりだ、という無常の思いをよんでいる。'], a: '季語=夏草、季節=夏、切れ字=や。昔、この平泉で武士たちが栄華や功名を夢見て戦ったが、今はそのあとに夏草がしげっているだけだ、という時の流れのはかなさをよんだ句。', check: '『平家物語』の「諸行無常」と同じように、栄えたものがやがて消えるという考えが共通していることに気づくと、理解が深まります。' }] },
      { h: '論語:孔子の教え', t: '【論語】は、古代中国の思想家【孔子】と、その弟子たちの言葉や行いを、弟子たちがまとめた書物です。孔子は、人を思いやる心(【仁】)や、学ぶことの大切さを説きました。文の初めの「子曰はく」は、「先生(孔子)がおっしゃるには」という意味です。\n「子曰はく、学びて時に之を習ふ、亦説ばしからずや。朋有り遠方より来たる、亦楽しからずや。人知らずして慍みず、亦君子ならずや。」\n現代語訳:先生がおっしゃった。「学んだことを機会があるたびに復習する、なんとうれしいことではないか。友人が遠くから訪ねてくる、なんと楽しいことではないか。人が自分を認めてくれなくても不満に思わない、なんと君子(人格のすぐれた人)ではないか。」\nほかの有名な言葉:【故きを温めて新しきを知る】(古いことを学び直して、新しい知識や考えを得る。「温故知新」の由来)。【学びて思はざれば則ち罔し。思ひて学ばざれば則ち殆ふし】(学んでも自分で考えなければ、はっきりとは分からない。考えても学ばなければ、ひとりよがりになって危うい)。【己の欲せざる所は人に施すこと勿かれ】(自分がされたくないことは、人にしてはならない)。【過ぎたるは猶ほ及ばざるがごとし】(やりすぎは、足りないのと同じようによくない)。\n「亦〜ずや」は「なんと〜ではないか」という感動を表す言い方です。',
        key: '論語=孔子と弟子の言行録。「子曰はく」=先生がおっしゃるには。温故知新・己の欲せざる所は人に施すこと勿かれ。',
        ex: [{ q: '「学びて思はざれば則ち罔し。思ひて学ばざれば則ち殆ふし。」は、どのようなことを言っているか説明しよう。', hint: '前半と後半が対になっています。「罔し」=はっきりしない、「殆ふし」=危うい、です。', steps: ['前半:「学びて思はざれば」=学んでも考えなければ、「罔し」=はっきりとは分からない。', '後半:「思ひて学ばざれば」=考えても学ばなければ、「殆ふし」=危うい(ひとりよがりになる)。', '前半と後半を合わせると、学ぶことと考えることの両方が必要だということになる。'], a: '学ぶだけで自分で考えなければ本当には理解できず、考えるだけで学ばなければひとりよがりになって危うい。学ぶことと考えることの両方が大切だということ。', check: '前半と後半が反対の組み合わせ(学ぶ・考えない/考える・学ばない)になっていることを確かめると、意味を取りちがえにくくなります。' }] }
    ],
    faq: [['古典の作品名と作者は、どうやって覚えればいい?', '「平安:竹取物語(作者不明・物語)、枕草子(清少納言・随筆)」「鎌倉:平家物語(軍記物語)、徒然草(兼好法師・随筆)」「江戸:おくのほそ道(松尾芭蕉・紀行文)」と、時代ごとに表にしましょう。冒頭文を声に出して読むと、作品と結びついて忘れにくくなります。'], ['初めて読む古文が出たら、どうすればいい?', '入試の古文には、ふつう現代語訳や注がついています。まず注と訳に目を通し、登場人物と「だれが何をしたか」を整理してから設問を読みます。主語が省略されている部分は、前の文から補いましょう。'], ['論語の「君子」とはどんな人?', '人格がすぐれ、徳のある立派な人のことです。論語では、目先の利益より正しいことを大切にする人として、よく「小人」(つまらない人)と対比されます。']],
    terms: [['随筆', '見聞きしたことや感じたことを、自由に書いた文章(枕草子・徒然草)'], ['軍記物語', '戦いをえがいた物語(平家物語)'], ['紀行文', '旅の体験や見聞を書いた文章(おくのほそ道)'], ['諸行無常', 'すべてのものは移り変わり、変わらないものはないという考え'], ['をかし', '趣がある、明るく知的な美しさを感じること'], ['対句', '形や意味のそろった2つの句を並べる表現'], ['切れ字', '俳句で感動を表し、切れ目を作る言葉(や・かな・けり)'], ['子曰はく', '「先生(孔子)がおっしゃるには」という論語の書き出し']],
    miss: ['『枕草子』と『徒然草』の作者や時代を取りちがえる。枕草子=平安・清少納言、徒然草=鎌倉・兼好法師と、時代ごとの表で覚える。', '古語の「うつくし」を「美しい」、「つとめて」を「努力して」と今の意味で訳す。今と意味がちがう古語をまとめて覚えて防ぐ。', '『平家物語』を随筆、『おくのほそ道』を物語とするなど、ジャンルをまちがえる。作品名・作者・時代・ジャンルの4つをセットで覚える。', '俳句の季語の季節を今の感覚で判断する。五月雨(梅雨の長雨)は夏の季語のように、旧暦の季節で決まることに注意する。'],
    sum: ['竹取物語=平安初期・作者不明・現存最古の物語。かぐや姫が月へ帰る話。', '枕草子=平安中期・清少納言・随筆。「春はあけぼの」、をかしの文学。', '平家物語=鎌倉・軍記物語・琵琶法師。諸行無常・盛者必衰、冒頭は対句。', '徒然草=鎌倉末期・兼好法師・随筆。「つれづれなるままに」「先達はあらまほしき事なり」。', 'おくのほそ道=江戸・松尾芭蕉・紀行文。「月日は百代の過客にして」「夏草や兵どもが夢の跡」。論語=孔子と弟子の言行録。'],
    next: '古文のきまりをさらにくわしく学ぶなら、高校の「古文の基礎(j_h1)」へ進みましょう。'
  };

  // ===== 中学国語:作文・条件作文 =====
  L.j_sakubun = {
    goal: '条件作文の条件を正確に読み取り、資料から読み取ったことと自分の意見・体験を二段落で組み立てて、原稿用紙のきまりを守って書けるようになる。',
    intro: '作文は「何を書けばいいか分からない」「時間内に書き終わらない」と苦手にする人が多い分野です。でも、入試の作文は自由作文ではありません。条件にしたがって、決まった型で書けば、だれでも安定して点が取れます。この単元では、書く前の準備から、組み立て、原稿用紙の使い方、見直しまで、得点につながる手順を身につけます。',
    pre: '【意見文】は、ある問題について自分の考えを述べ、理由や体験をあげて読む人を納得させる文章です。基本の形は「主張→理由→具体例→まとめ」です。\n【常体】は「〜だ・〜である」、【敬体】は「〜です・〜ます」で終わる文体です。1つの作文の中では、どちらかに【統一】します。\n【段落】は内容のまとまりです。書き出しと段落の初めは1マス下げて書きます。\n高校入試の作文では、【条件作文】がよく出ます。字数(「200字以上250字以内」など)、段落数(「二段落構成で」)、内容(「資料から読み取ったことをふまえて」「自分の体験を入れて」)などの条件にしたがって書く作文です。',
    secs: [
      { h: '条件を読み取ることから始める', t: 'なぜ条件がいちばん大切なのでしょうか。条件作文の採点は、まず「条件を守っているか」から始まり、条件を1つ落とすだけで大きく減点されるからです。内容がよくても、字数が足りなかったり、段落数がちがったりすると点になりません。\n書く前に、問題文の条件に線を引き、①②③と番号をつけます。よく出る条件は次のとおりです。\n【字数】…「〇字以上〇字以内」。「以内」を1字でもこえると大きな減点になります。下限がない場合も、指定字数の8割以上を目安にしましょう。\n【段落数】…「二段落構成で」。段落の数と、それぞれの段落に書く内容が指定されることが多いです。\n【内容】…「資料から読み取ったことを書く」「自分の体験をふまえる」「賛成か反対かを明らかにする」など。\n【形式】…「題名や氏名は書かない」「原稿用紙の正しい使い方にしたがう」など。',
        key: '書く前に条件に線を引いて番号をつけ、書いた後に1つずつチェックする。「以内」は1字もこえない。',
        ex: [{ q: '次の条件を読み、守るべきことを箇条書きにしよう。\n「資料を見て気づいたことと、それをふまえたあなたの考えを、二段落構成で、百六十字以上二百字以内で書きなさい。ただし、第二段落には自分の体験を入れること。」', hint: '字数・段落・内容の順に分けて整理しましょう。', steps: ['字数:160字以上200字以内。', '段落:二段落構成。', '第一段落:資料を見て気づいたことを書く。', '第二段落:資料をふまえた自分の考えと、自分の体験を書く。'], a: '①160〜200字 ②二段落 ③第一段落=資料から気づいたこと ④第二段落=自分の考え＋自分の体験', check: '問題文にもどり、線を引いた条件がすべて箇条書きに入っているかを確かめます。' }] },
      { h: '二段落構成の型', t: '入試の作文で最もよく使われるのが【二段落構成】です。前の段落で「事実」、後の段落で「意見」を書くと、読み手に筋道が伝わりやすくなります。\n【第一段落】(全体の4割程度)…資料やテーマから読み取ったこと・気づいたことを書きます。「資料から、〜ということが分かる。」のように、事実を正確に書きます。\n【第二段落】(全体の6割程度)…第一段落をふまえた自分の意見と、その根拠になる体験を書きます。「私は、〜と考える。なぜなら〜からだ。」→「実際に私は〜」→「だから、〜していきたい。」\n第二段落の最後は、意見をもう一度短くまとめてしめくくると、まとまりのある作文になります。\n書き始める前に、段落ごとに「何を書くか」を1行ずつメモすると、途中で話がそれたり、時間が足りなくなったりするのを防げます。',
        key: '第一段落=資料から読み取った事実、第二段落=意見＋根拠となる体験＋まとめ。' },
      { h: '資料(グラフ・表)の読み取り方', t: '資料を使う作文では、まず資料を【正確に】読み取ることが大切です。数値を読みまちがえたり、資料にないことを書いたりすると、それだけで減点されます。\n読み取りの手順:①タイトル・単位(%・人・時間)・調査した年や対象を確かめる。②いちばん大きい(小さい)もの、増えた(減った)ものなど、目立つ特徴を見つける。③2つ以上のものを比べて、ちがいや変化を言葉にする。\n【割合の変化】に注意しましょう。20%から32%に増えたときは「12ポイント増えた」と言います。「12%増えた」とすると、20%の12%増し(約22%)と誤解されるおそれがあります。また、32÷20=1.6なので「1.6倍になった」と言うこともできます。\n書き方の例:「資料から、1日に3時間以上スマートフォンを使う中学生の割合が、2020年の20%から2024年には32%へと増えていることが分かる。」\n資料から言えることと、自分の考えは分けて書きます。「増えている」は資料から言える事実ですが、「使いすぎはよくない」は自分の意見です。',
        key: '資料はタイトル・単位・年を確かめ、特徴を正確に書く。割合の差は「ポイント」。事実と意見を分ける。',
        ex: [{ q: '資料「地域の行事に参加したことがある中学生の割合:A市 70%、B市 45%」から読み取れることを、1文で書こう。', hint: '2つの市を比べ、差を数値で表しましょう。', steps: ['比べているのは、A市とB市の中学生の割合。', 'A市は70%、B市は45%で、A市のほうが高い。', '差は70−45=25で、25ポイント。', '事実だけを1文にまとめ、自分の意見は入れない。'], a: '(解答例)地域の行事に参加したことがある中学生の割合は、A市が70%で、B市の45%より25ポイント高い。', check: '「25%高い」としていないか、資料にない「A市のほうが地域を大切にしている」などの意見を書いていないかを確かめます。' }] },
      { h: '意見と体験の書き方', t: '第二段落で大切なのは、【意見】と【体験】がしっかり結びついていることです。体験は、意見に説得力をもたせる【根拠】として書きます。\n意見の書き方:「私は、〜と考える。」「私は、〜するべきだと思う。」と、はっきり言い切ります。「〜かもしれない」「〜と思わなくもない」のようなあいまいな書き方は、主張が弱くなります。\n体験の書き方:「たとえば、私は〜したとき、〜ということに気づいた。」のように、いつ・何をして・何に気づいたかを具体的に書きます。体験の説明が長くなりすぎないよう、2〜3文におさえます。\n【反対意見への答え】を入れると、さらに説得力が増します。「確かに、〜という考えもある。しかし、〜。」\nまとめ:「だから私は、これから〜していきたい。」のように、意見をくり返し、これからの自分の行動につなげると、しめくくりがはっきりします。',
        key: '意見は言い切る。体験は「いつ・何をして・何に気づいたか」を2〜3文で、意見の根拠として書く。',
        ex: [{ q: '「読書の大切さ」について、意見の1文と、それを支える体験の文を書こう。', hint: '先に意見を言い切り、その意見に合う体験を選びましょう。', steps: ['意見を言い切る:「私は、読書は自分の世界を広げてくれると考える。」', '意見を支える体験を選ぶ(本を読んで気づいたこと)。', '体験を、いつ・何をして・何に気づいたかの順に書く。', '体験が意見とつながっているかを確かめる。'], a: '(解答例)私は、読書は自分の世界を広げてくれると考える。たとえば、中学一年生のとき、宇宙飛行士の伝記を読んで、それまで興味のなかった宇宙のことを自分で調べるようになった。', check: '体験の内容(宇宙に興味をもつようになった)が、意見(世界が広がる)の具体例になっているかを確かめます。' }] },
      { h: '原稿用紙の使い方', t: '原稿用紙の使い方も採点の対象です。きまりを守ると、読みやすく、ていねいな印象の答案になります。\n【書き出しと段落】…書き出しと、段落の初めは1マス空けます。段落を変えるときは行を改めます。\n【句読点・かっこ】…句点(。)・読点(、)・かぎかっこ(「 」)は、それぞれ1マスに書きます。\n【行頭のきまり】…句読点や閉じかぎ(」)が行の最初のマスに来るときは、前の行の最後のマスに、文字といっしょに書きます(マスの下の余白に書いてもかまいません)。\n【小さい字】…「っ」「ゃ」「ゅ」「ょ」などの小さい字も1マスに書きます。\n【会話の終わり】…会話の終わりの句点と閉じかぎ(。」)は、同じ1マスに書くのが一般的です。\n【数字】…縦書きでは、ふつう漢数字(一・二・三、二〇二四年)を使います。\n題名や氏名を書くかどうかは問題の指示にしたがいます。入試では「題名や氏名は書かないこと」とされることが多いです。',
        key: '段落の初めは1マス空け。句読点・閉じかぎは行頭に置かず前の行の最後のマスへ。縦書きは漢数字。' },
      { h: '時間内に書き上げる手順と見直し', t: '入試の作文は、限られた時間で書き上げなければなりません。次の手順で進めると、書き直しが少なくなります。\n①【条件に線を引く】(1分)…字数・段落・内容の条件を確認します。\n②【メモを作る】(2〜3分)…段落ごとに書くことを1行ずつメモします。第二段落の意見と体験を先に決めると、全体がぶれません。\n③【書く】…メモにそって一気に書きます。むずかしい言葉より、正しく分かりやすい言葉を選びます。\n④【見直す】(2〜3分)…条件(字数・段落数・内容)、文体の統一(常体と敬体が混ざっていないか)、誤字・脱字、原稿用紙のきまり、主語と述語のねじれ、の順に確かめます。\n【主語と述語のねじれ】とは、「私の夢は、医者になりたい。」のように、主語と述語がかみ合っていない文のことです。「私の夢は、医者になることだ。」と直します。',
        key: '条件に線→メモ→書く→見直し(条件・文体・誤字・原稿用紙・主語と述語のねじれ)。',
        ex: [{ q: '次の文の主語と述語のねじれを直そう。\n「私が作文で大切だと思うことは、最初にメモを作る。」', hint: '主語「〜ことは」に合う述語の形を考えましょう。', steps: ['主語は「私が作文で大切だと思うことは」。', '述語「メモを作る」は動作なので、「ことは」とかみ合っていない。', '「〜ことは、〜ことだ」の形にそろえる。'], a: '私が作文で大切だと思うことは、最初にメモを作ることだ。', check: '主語と述語だけを取り出して「ことは…ことだ」と読み、意味が通るかを確かめます。' }] }
    ],
    faq: [['字数がどうしても足りないときは、どうすればいい?', '体験の部分をくわしくしましょう。「そのとき、どう感じたか」「そこから何に気づいたか」を1文加えると、内容も深まり字数も増えます。同じ内容のくり返しや、資料の数値の書き写しで字数をかせぐのはやめましょう。'], ['常体と敬体、どちらで書くほうがいいの?', '問題に指定がなければどちらでもかまいません。意見文は常体(〜だ・〜である)のほうが、言い切りやすく字数も節約できます。大切なのは、最後まで1つの文体に統一することです。'], ['書いている途中でまちがいに気づいたら?', '消しゴムできれいに消して書き直します。字数が大きく変わる書き直しは時間がかかるので、書く前のメモをしっかり作っておくことが、いちばんの対策です。']],
    terms: [['条件作文', '字数・段落数・内容などの条件にしたがって書く作文'], ['二段落構成', '第一段落に事実(資料)、第二段落に意見と体験を書く組み立て'], ['常体・敬体', '「〜だ・〜である」の文体と「〜です・〜ます」の文体'], ['ポイント', '割合(%)どうしの差を表す単位'], ['根拠', '意見を支える理由や具体的な事実・体験'], ['主語と述語のねじれ', '主語と述語がかみ合っていない文']],
    miss: ['「以内」の字数を少しこえてしまう。書く前のメモで分量を決め、書いた後に最後の行の位置で字数を必ず確かめる。', '常体と敬体が混ざる。書き始める前に文体を決め、見直しで文末だけを順に読んで確かめる。', '資料の割合の差を「〇%増えた」と書いたり、資料にないことを事実のように書いたりする。割合の差は「ポイント」、資料から言えることと自分の意見を分けて書く。', '体験だけを長く書き、意見がはっきりしない。意見を先に言い切り、体験は2〜3文で意見の根拠として書く。', '句読点や閉じかぎを行の最初のマスに書く。前の行の最後のマスに、文字といっしょに入れる。'],
    sum: ['書く前に条件に線を引いて番号をつけ、書いた後に1つずつ確かめる。', '基本は二段落構成:第一段落=資料から読み取った事実、第二段落=意見＋体験＋まとめ。', '資料はタイトル・単位・年を確かめて正確に読み、割合の差は「ポイント」で表す。', '意見ははっきり言い切り、体験は意見の根拠として具体的に短く書く。', '原稿用紙のきまり(段落の1マス空け・句読点の位置・漢数字)と文体の統一を守る。'],
    next: '意見文の土台になる読み方は「説明的文章の読解(j_setsumei)」で確かめましょう。高校では「国語表現(j_hyogen)」で小論文に発展します。'
  };
})(WPS.LESSONS);
